        // 2. Firm Mirror Trailing DD Integration
        private static void TestFirmMirrorTrailingDDBreachEmitsAction()
        {
            Console.WriteLine("\n[TEST] Firm Mirror Trailing DD Breach Emits Action And Locks Out");
            var account = new Account { Name = "FirmAcc" };
            var addon = new RiskGuardAddOn();
            
            var fmConfig = new FirmMirrorConfig();
            fmConfig.Enabled = true;
            fmConfig.TrailingDD.Enabled = true;
            fmConfig.TrailingDD.Amount = 2500;
            fmConfig.TrailingDD.Buffer = 300;
            
            var config = new RiskConfig();
            config.FirmMirror = fmConfig;
            addon.SetConfigForTest(config);
            
            var state = new AccountState("FirmAcc");
            state.FirmStartingBalance = 100000;
            state.FirmTrailingPeak = 100000;
            
            account.Values[AccountItem.CashValue] = 97000.0;
            account.Values[AccountItem.UnrealizedProfitLoss] = 0.0;
            account.Values[AccountItem.RealizedProfitLoss] = -3000.0;

            // Fixed clock. DateTime.UtcNow made this test time-of-day dependent: past the
            // FirmMirror daily-reset boundary (DailyResetHourUtc, default 22:00 UTC) the firm
            // session rolls over and rebases the P&L, so the breach no longer fires.
            var nowUtc = FirmTestClockUtc;
            state.FirmDailyDate = FirmDailyDateFor(nowUtc, fmConfig);

            var actions = addon.EvaluateFirmMirror(account, state, nowUtc);
            
            Assert(actions.Any(a => a.RuleId == "FIRM_TRAILING_DD_BREACH"), "Firm trailing DD breach action generated");
            Assert(state.IsLockedOut == true, "Firm mirror breach locks out account");
        }

        // P1-42: EvaluateFirmMirror passed the TOP-LEVEL FirmMirrorConfig straight into
        // ComputeFirmMirror, which reads only fm.TrailingDD / fm.DailyLoss. AccountFirmMap and
        // FirmProfiles were consulted by no evaluation path at all -- the only reference to
        // AccountFirmMap in the addon was RunPreflight's validation, which checks that mapped
        // firms exist. So preflight validated a mapping that nothing read, and the researched
        // per-firm numbers were dead config. This test uses the exact live shape observed on
        // 2026-08-07: top-level sub-rules disabled, real firm profiles present, and a funded
        // TakeProfit Trader account that consequently had no firm protection whatsoever.
        private static void TestP1_42_MappedAccountIsEvaluatedAgainstItsFirmProfile()
        {
            Console.WriteLine("\n[TEST] P1-42: a mapped account must be evaluated against its firm profile");

            Func<FirmMirrorConfig> liveShape = () =>
            {
                var fm = new FirmMirrorConfig();
                fm.Enabled = true;
                fm.TrailingDD.Enabled = false;   // as live: top-level sub-rules are OFF
                fm.DailyLoss.Enabled = false;
                fm.FirmProfiles["TakeProfitTrader"] = new FirmProfile
                {
                    Name = "TakeProfitTrader",
                    TrailingDD = new FirmTrailingDDConfig
                    {
                        Enabled = true, Type = "eod", IncludesUnrealized = false,
                        Amount = 1500.0, Buffer = 200.0, LockAtProfit = 0.0
                    },
                    DailyLoss = new FirmDailyLossConfig { Enabled = false, Basis = "realized" }
                };
                return fm;
            };

            Func<FirmMirrorConfig, string, List<GuardAction>> evaluate = (fm, accountName) =>
            {
                var account = new Account { Name = accountName };
                var addon = new RiskGuardAddOn();
                var config = new RiskConfig();
                config.FirmMirror = fm;
                addon.SetConfigForTest(config);

                var state = new AccountState(accountName);
                state.FirmStartingBalance = 50000.0;
                state.FirmTrailingPeak = 50000.0;
                // floor = 50000 - 1500 + 200 = 48700; equity 48000 is below it.
                account.Values[AccountItem.CashValue] = 48000.0;
                account.Values[AccountItem.UnrealizedProfitLoss] = 0.0;
                account.Values[AccountItem.RealizedProfitLoss] = -2000.0;
                state.FirmDailyDate = FirmDailyDateFor(FirmTestClockUtc, fm);
                return addon.EvaluateFirmMirror(account, state, FirmTestClockUtc);
            };

            // The live case: mapped account, top-level disabled, profile enabled.
            var mapped = liveShape();
            mapped.AccountFirmMap["TAKEPROFITPRO524207503"] = "TakeProfitTrader";
            Assert(evaluate(mapped, "TAKEPROFITPRO524207503").Any(a => a.RuleId == "FIRM_TRAILING_DD_BREACH"),
                "a mapped account must breach on its firm profile's numbers even though the top-level rule is disabled");

            // An account that is NOT mapped must keep falling back to the top-level pair,
            // which here is disabled -- it must not inherit some other firm's profile.
            var unmappedFm = liveShape();
            unmappedFm.AccountFirmMap["SomeOtherAccount"] = "TakeProfitTrader";
            Assert(!evaluate(unmappedFm, "TAKEPROFITPRO524207503").Any(a => a.RuleId == "FIRM_TRAILING_DD_BREACH"),
                "an unmapped account must not pick up another account's firm profile");

            // Fallback must still work in the positive direction: unmapped + top-level enabled.
            var topLevel = liveShape();
            topLevel.TrailingDD.Enabled = true;
            topLevel.TrailingDD.Type = "eod";
            topLevel.TrailingDD.Amount = 1500.0;
            topLevel.TrailingDD.Buffer = 200.0;
            Assert(evaluate(topLevel, "UnmappedAcc").Any(a => a.RuleId == "FIRM_TRAILING_DD_BREACH"),
                "an unmapped account must still be evaluated against the top-level rule");

            // A mapping to a firm that is absent from FirmProfiles must fall back, not throw.
            // Preflight blocks arming in that case, but the evaluator must not depend on
            // preflight having run -- config can be reloaded while armed.
            var danglingFm = liveShape();
            danglingFm.TrailingDD.Enabled = true;
            danglingFm.TrailingDD.Type = "eod";
            danglingFm.TrailingDD.Amount = 1500.0;
            danglingFm.TrailingDD.Buffer = 200.0;
            danglingFm.AccountFirmMap["DanglingAcc"] = "NoSuchFirm";
            Assert(evaluate(danglingFm, "DanglingAcc").Any(a => a.RuleId == "FIRM_TRAILING_DD_BREACH"),
                "a mapping to an unknown firm must fall back to the top-level rule rather than throw or silently disable");

            // Both dictionaries are OrdinalIgnoreCase; resolution must honour that.
            var casedFm = liveShape();
            casedFm.AccountFirmMap["takeprofitpro524207503"] = "takeprofittrader";
            Assert(evaluate(casedFm, "TAKEPROFITPRO524207503").Any(a => a.RuleId == "FIRM_TRAILING_DD_BREACH"),
                "account and firm lookup must stay case-insensitive");

            // The profile's DailyLoss must resolve too, not just TrailingDD.
            var dailyFm = liveShape();
            dailyFm.FirmProfiles["Tradeify"] = new FirmProfile
            {
                Name = "Tradeify",
                TrailingDD = new FirmTrailingDDConfig { Enabled = false },
                DailyLoss = new FirmDailyLossConfig
                {
                    Enabled = true, Basis = "realized", Amount = 1250.0, Buffer = 100.0
                }
            };
            dailyFm.AccountFirmMap["TradeifyAcc"] = "Tradeify";
            Assert(evaluate(dailyFm, "TradeifyAcc").Any(a => a.RuleId == "FIRM_DAILY_LOSS_BREACH"),
                "a mapped account's firm DailyLoss rule must be evaluated (-2000 breaches a 1250/100 limit)");
        }

        // ================================================================================
        // F-9 -- the account -> firm-plan mapping. docs/UI_REDESIGN_DESIGN.md section 9.
        //
        // P1-42 made the ENFORCER read AccountFirmMap/FirmProfiles. The REPORTER never
        // followed. GuardRules' two firm rules branch on the TOP-LEVEL
        // FirmMirror.TrailingDD.Enabled / DailyLoss.Enabled and report the TOP-LEVEL Amount,
        // while EvaluateFirmMirror resolves a per-account effective config first.
        //
        // In the shape the researched profiles actually use -- top-level sub-rules OFF, the
        // firm profile's ON -- those two disagree in the reassuring direction's mirror image:
        // the enforcer flattens and locks out on the profile's numbers while the inventory
        // reports "Disabled - firm trailing drawdown not enabled". And in the TPT shape,
        // whose profile has DailyLoss OFF, the disagreement runs the dangerous way: the
        // inventory reports a live daily-loss rule that cannot fire.
        //
        // This is P1-42's own lesson applied to the reporter -- "logging the top-level
        // amounts while breaching on a profile's would make the audit trail describe a rule
        // that did not run" -- and it was latent only because AccountFirmMap was EMPTY. F-9
        // populates it, so F-9 activates it.
        // ================================================================================

        /// <summary>One combination of the four switches that decide whether a firm rule runs.</summary>
        private class F9Shape
        {
            public string Label;
            public bool MasterEnabled;
            public bool TopLevelEnabled;
            public bool ProfilePresent;
            public bool ProfileEnabled;
            public bool Mapped;
        }

        private const string F9Plan = "TakeProfitTrader-50K";
        private const string F9Account = "F9Acc";

        /// <summary>
        /// The live/researched shape, parameterised. Top-level amounts are deliberately DIFFERENT
        /// from the profile's (2500/1500 vs 1500/1250) so a reporter reading the wrong one is
        /// visible as a number, not just as a state.
        /// </summary>
        private static FirmMirrorConfig F9Config(F9Shape s, bool trailing)
        {
            var fm = new FirmMirrorConfig();
            fm.Enabled = s.MasterEnabled;
            fm.TrailingDD.Enabled = trailing && s.TopLevelEnabled;
            fm.TrailingDD.Type = "eod";
            fm.TrailingDD.IncludesUnrealized = false;
            fm.TrailingDD.Amount = 2500.0;
            fm.TrailingDD.Buffer = 200.0;
            fm.DailyLoss.Enabled = !trailing && s.TopLevelEnabled;
            fm.DailyLoss.Basis = "realized";
            fm.DailyLoss.Amount = 1500.0;
            fm.DailyLoss.Buffer = 200.0;

            if (s.ProfilePresent)
            {
                fm.FirmProfiles[F9Plan] = new FirmProfile
                {
                    Name = F9Plan,
                    TrailingDD = new FirmTrailingDDConfig
                    {
                        Enabled = trailing && s.ProfileEnabled, Type = "eod",
                        IncludesUnrealized = false, Amount = 1500.0, Buffer = 200.0
                    },
                    DailyLoss = new FirmDailyLossConfig
                    {
                        Enabled = !trailing && s.ProfileEnabled, Basis = "realized",
                        Amount = 1250.0, Buffer = 100.0
                    }
                };
            }
            if (s.Mapped) fm.AccountFirmMap[F9Account] = F9Plan;
            return fm;
        }

        /// <summary>
        /// Runs the REPORTER over one firm rule for one account, and returns the state a UI
        /// would render. guardCanAct is true and the account is not excluded -- the most
        /// permissive input, so anything that comes back Disabled did so on its own merits.
        /// </summary>
        private static GuardRuleState F9ReporterState(
            FirmMirrorConfig fm, string accountName, string configPath, out GuardRuleReading reading)
        {
            var cfg = new RiskConfig();
            cfg.FirmMirror = fm;
            var rule = GuardRuleRegistry.Rules.First(
                r => string.Equals(r.ConfigPath, configPath, StringComparison.OrdinalIgnoreCase));
            var acct = Ui4Account(accountName, equity: 48000.0);
            var ctx = new GuardRuleContext
            {
                AccountName = accountName,
                Config = cfg,
                PropConfig = new PropFirmProtectionConfig(),
                Account = acct,
                AllAccounts = new List<RiskGuardAddOn.AccountStateSnapshot> { acct },
                NewsEventCount = 0
            };
            reading = rule.Evaluator(ctx);
            return GuardRuleRegistry.DeriveState(rule, reading, true, false);
        }

        /// <summary>
        /// Runs the ENFORCER over the same config, and answers "could this rule fire at all?".
        ///
        /// Two details make the probe honest, and the first draft got both wrong.
        ///
        /// (1) The inputs must breach EVERY amount in play, not just the smallest. A 50k start
        /// with equity 48000 breaches the plan's 1500 floor (48700) but NOT the top-level 2500
        /// floor (47700), so four shapes came back "silent" for a rule that was running fine and
        /// would have been recorded as reporter defects. Equity 30000 and -10000 realized are
        /// below every floor and every daily limit here, so "silent" means "cannot fire" rather
        /// than "did not happen to breach".
        ///
        /// (2) `ComputeFirmMirror` does not check `FirmMirror.Enabled` -- the master switch is
        /// applied by the CALLERS at RiskGuardAddOn.cs:1431 and :1502. A probe that calls
        /// EvaluateFirmMirror directly therefore fires with the master switch OFF, which is not
        /// what the deployed system does. The gate is applied here so the probe measures the
        /// enforcer as it actually runs.
        /// </summary>
        private static bool F9EnforcerFires(FirmMirrorConfig fm, string accountName, string ruleId)
        {
            if (fm == null || !fm.Enabled) return false;

            var account = new Account { Name = accountName };
            var addon = new RiskGuardAddOn();
            var config = new RiskConfig();
            config.FirmMirror = fm;
            addon.SetConfigForTest(config);

            var state = new AccountState(accountName);
            state.FirmStartingBalance = 50000.0;
            state.FirmTrailingPeak = 50000.0;
            state.FirmDailyDate = FirmDailyDateFor(FirmTestClockUtc, fm);
            account.Values[AccountItem.CashValue] = 30000.0;
            account.Values[AccountItem.UnrealizedProfitLoss] = 0.0;
            account.Values[AccountItem.RealizedProfitLoss] = -10000.0;

            return addon.EvaluateFirmMirror(account, state, FirmTestClockUtc)
                        .Any(a => a.RuleId == ruleId);
        }

        /// <summary>
        /// THE CLASS TEST. For every combination of the four switches, and for BOTH firm rules,
        /// the reporter saying "Disabled" must mean the enforcer cannot fire, and the reporter
        /// not saying it must mean the enforcer can.
        ///
        /// The expectation is DERIVED FROM THE ENFORCER rather than restated by hand. That is
        /// the whole point: a hand-written table of expected states would have to be updated by
        /// whoever next changes the resolution order, which is exactly the person who would get
        /// it wrong. Any future divergence between the two paths fails here without anyone
        /// having thought of the specific case.
        /// </summary>
        private static void TestF9_TheReporterAndTheEnforcerAgreeOnEveryFirmShape()
        {
            Console.WriteLine("\n[TEST] F-9: the firm-rule reporter and the firm-rule enforcer agree on every shape");

            var shapes = new List<F9Shape>();
            foreach (bool master in new[] { true, false })
            foreach (bool top in new[] { true, false })
            foreach (bool present in new[] { true, false })
            foreach (bool profOn in new[] { true, false })
            foreach (bool mapped in new[] { true, false })
            {
                if (!present && profOn) continue;   // a profile cannot be enabled if it is absent
                shapes.Add(new F9Shape
                {
                    Label = string.Format("master={0} top={1} profile={2}/{3} mapped={4}",
                        master, top, present ? "present" : "absent", profOn ? "on" : "off", mapped),
                    MasterEnabled = master, TopLevelEnabled = top,
                    ProfilePresent = present, ProfileEnabled = profOn, Mapped = mapped
                });
            }

            var disagreements = new List<string>();
            int compared = 0;
            foreach (var trailing in new[] { true, false })
            {
                string configPath = trailing ? "FirmMirror.TrailingDD.Amount" : "FirmMirror.DailyLoss.Amount";
                string ruleId = trailing ? "FIRM_TRAILING_DD_BREACH" : "FIRM_DAILY_LOSS_BREACH";
                foreach (var s in shapes)
                {
                    GuardRuleReading reading;
                    var reported = F9ReporterState(F9Config(s, trailing), F9Account, configPath, out reading);
                    bool fires = F9EnforcerFires(F9Config(s, trailing), F9Account, ruleId);
                    compared++;

                    bool reportedOff = reported == GuardRuleState.Disabled;
                    if (reportedOff == fires)
                    {
                        disagreements.Add(string.Format("{0} [{1}]: reporter={2} enforcer={3}",
                            configPath, s.Label, reported, fires ? "FIRES" : "silent"));
                    }
                }
            }

            Assert(compared >= 40 && disagreements.Count == 0, string.Format(
                "across {0} shape/rule combinations the reporter never calls a rule Disabled that "
                + "the enforcer runs, nor calls one live that cannot fire ({1} disagreed{2})",
                compared, disagreements.Count,
                disagreements.Count == 0 ? "" : ": " + string.Join(" | ", disagreements.Take(6))));
        }

        /// <summary>
        /// The number a UI renders beside a mapped account must be the number in force. The
        /// state test above cannot catch this: reporting Evaluated with the top-level 2500 while
        /// the guard enforces the profile's 1500 passes every state assertion and still tells the
        /// operator a limit they do not have.
        /// </summary>
        private static void TestF9_TheReportedLimitIsTheOneInForceAndNamesThePlan()
        {
            Console.WriteLine("\n[TEST] F-9: a mapped account's reported firm limit is its plan's, and the note names the plan");

            // The live/researched shape: master on, top-level OFF, profile ON, account mapped.
            var live = new F9Shape
            {
                MasterEnabled = true, TopLevelEnabled = false,
                ProfilePresent = true, ProfileEnabled = true, Mapped = true
            };

            GuardRuleReading trailingReading;
            var trailingState = F9ReporterState(
                F9Config(live, true), F9Account, "FirmMirror.TrailingDD.Amount", out trailingReading);

            Assert(trailingState != GuardRuleState.Disabled
                   && trailingReading != null
                   && trailingReading.Limit.HasValue
                   && Math.Abs(trailingReading.Limit.Value - 1500.0) < 0.001,
                string.Format("the trailing-drawdown limit reported is the plan's 1500, not the top-level 2500 (got {0}, state {1})",
                    trailingReading == null || !trailingReading.Limit.HasValue ? "null" : trailingReading.Limit.Value.ToString(),
                    trailingState));

            Assert(trailingReading != null && !string.IsNullOrEmpty(trailingReading.Note)
                   && trailingReading.Note.IndexOf(F9Plan, StringComparison.OrdinalIgnoreCase) >= 0,
                "the note names the firm plan the account resolved to, so the operator can check it against the firm's rulebook");

            // The daily-loss rule on the same shape resolves to the plan's 1250. Sign convention
            // follows the existing rule, which reports the limit as a negative number.
            GuardRuleReading dailyReading;
            var dailyState = F9ReporterState(
                F9Config(live, false), F9Account, "FirmMirror.DailyLoss.Amount", out dailyReading);

            // The sign is asserted EXACTLY, not through Math.Abs. The rule has reported the daily
            // limit as a negative number since it was written, next to a RealizedPnL that is also
            // negative, and a UI comparing the two would render a loss as being under a POSITIVE
            // limit if the sign flipped. The first draft of this assertion wrapped the reading in
            // Math.Abs to avoid committing to the convention, which left a sign flip unpinned --
            // a mutant survived it.
            Assert(dailyState != GuardRuleState.Disabled
                   && dailyReading != null
                   && dailyReading.Limit.HasValue
                   && Math.Abs(dailyReading.Limit.Value - (-1250.0)) < 0.001,
                string.Format("the daily-loss limit reported is the plan's 1250, negative by convention, not the top-level 1500 (got {0}, state {1})",
                    dailyReading == null || !dailyReading.Limit.HasValue ? "null" : dailyReading.Limit.Value.ToString(),
                    dailyState));

            // A mapping to a firm that is absent from FirmProfiles must not read as protection.
            // Preflight refuses to arm on it (P2-8), but config can be reloaded while armed, so
            // the reporter has to say what is actually in force: the top-level fallback.
            var dangling = new F9Shape
            {
                MasterEnabled = true, TopLevelEnabled = true,
                ProfilePresent = false, ProfileEnabled = false, Mapped = true
            };
            GuardRuleReading danglingReading;
            F9ReporterState(F9Config(dangling, true), F9Account, "FirmMirror.TrailingDD.Amount", out danglingReading);
            Assert(danglingReading != null && !string.IsNullOrEmpty(danglingReading.Note)
                   && danglingReading.Note.IndexOf(F9Plan, StringComparison.OrdinalIgnoreCase) >= 0,
                "a mapping to an absent profile still names the firm it points at, so the operator can see WHICH mapping is broken");
        }

        /// <summary>
        /// The over-application guard. The cheapest way to make the shape test pass is to resolve
        /// the effective config and keep using AccountFirmMap.Count as the evidence -- at which
        /// point ONE mapped account turns every other account's firm rules green, including the
        /// 88 expired prop accounts the live box reports. The evidence for a PerAccount rule is
        /// whether THIS account is mapped.
        /// </summary>
        private static void TestF9_AnAccountAbsentFromAPopulatedMapIsInertNotGreen()
        {
            Console.WriteLine("\n[TEST] F-9: one mapped account does not make every other account's firm rules green");

            var fm = F9Config(new F9Shape
            {
                MasterEnabled = true, TopLevelEnabled = true,
                ProfilePresent = true, ProfileEnabled = true, Mapped = true
            }, true);
            // Two more accounts mapped, so the map is populated and Count is 3 -- the number a
            // naive evaluator would report as evidence for an account that is in none of them.
            fm.AccountFirmMap["SomeOtherAccount"] = F9Plan;
            fm.AccountFirmMap["AndAnother"] = F9Plan;

            GuardRuleReading reading;
            var state = F9ReporterState(fm, "NotInTheMap", "FirmMirror.TrailingDD.Amount", out reading);

            Assert(state == GuardRuleState.Inert && reading != null && reading.EvidenceCount == 0,
                string.Format("an account absent from a 3-entry map reports Inert with 0 evidence, not {0} with {1}",
                    state, reading == null ? "null" : reading.EvidenceCount.ToString()));

            // And the paired positive: the account that IS mapped must not be dragged down with
            // it. Without this, `EvidenceCount = 0` unconditionally passes the assertion above.
            GuardRuleReading mappedReading;
            var mappedState = F9ReporterState(fm, F9Account, "FirmMirror.TrailingDD.Amount", out mappedReading);
            Assert(mappedState == GuardRuleState.Enforcing && mappedReading.EvidenceCount == 1,
                string.Format("the mapped account itself still reports Enforcing on 1 piece of evidence (got {0}/{1})",
                    mappedState, mappedReading == null ? "null" : mappedReading.EvidenceCount.ToString()));
        }

        /// <summary>
        /// The F-9 config as DEPLOYED must pass preflight, or the guard comes up DISARMED.
        ///
        /// This is not a hypothetical. `SaveAndReloadConfig` writes and reloads WITHOUT running
        /// preflight, so the mapping went live at 14:04 on a box that had armed at 14:03 against
        /// the previous config -- the live config had never been preflighted at all. The next
        /// restart runs it, and a `FIRM_MIRROR` failure there means `ARMED_ON_START` does not
        /// arm: no protection, and nothing about the config file looks wrong.
        ///
        /// There is no preflight endpoint on the bridge, so this is where that gets checked. The
        /// values are the ones actually POSTed to the box on 2026-08-13, transcribed from the
        /// `interventions.jsonl` audit record of the write, and the assertion is on the WHOLE
        /// preflight rather than the firm clause, because `PreflightResult.Fail` overwrites and
        /// any earlier failure would hide this one.
        /// </summary>
        private static void TestF9_TheDeployedFirmMappingPassesPreflight()
        {
            Console.WriteLine("\n[TEST] F-9: the firm mapping as deployed passes preflight, so the box can still arm");

            var previousAccounts = Account.All;
            try
            {
                // ⚠️ ALL FIVE mapped accounts, with the equities the box actually reports.
                // The first draft of this test stubbed only ONE while mapping five, and asserted
                // that the deployed configuration arms -- so it claimed to pin the live mapping
                // while three quarters of it was untested. F-9b's account-exists check found that
                // the moment it existed, by regressing this test. The fixture was wrong and the
                // new check was right, which is the outcome a gate is for.
                Account.All = new List<Account>
                {
                    F9bAccount("Sim_All_Day_ORB", 49833.70),
                    F9bAccount("Sim-ORB", 100170.00),
                    F9bAccount("Sim101", 99482.00),
                    F9bAccount("SimCopy2", 98140.50),
                    F9bAccount("SimCopyTest1", 100511.50),
                    F9bAccount("TAKEPROFITPRO524207503", 50357.00),
                };

                var cfg = new RiskConfig();
                cfg.Mode = "shadow";
                cfg.FirmMirror.Enabled = true;
                // Top-level sub-rules stay OFF deliberately: an UNMAPPED account must get no firm
                // rule at all rather than the guessed 2500/1500, which is CONFIG_DEFAULTS R3 --
                // "the honest default is not a different number, it is no number".
                cfg.FirmMirror.TrailingDD.Enabled = false;
                cfg.FirmMirror.DailyLoss.Enabled = false;
                // ⚠️ THESE VALUES CAME FROM THE FIRMS' PUBLISHED TABLES, not from the config
                // backup, and the difference is the point. See docs/FIRM_PLANS_RESEARCH.md. The
                // profiles recovered from the 2026-08-07 backup carried NO account size, and the
                // sizes inferred for two of them were wrong: the "TakeProfitTrader" profile's 1500
                // is TPT's 25K max loss (a 50K is 2000) and the "Apex" profile's 2000/1000 is
                // Apex's 50K EOD row exactly (a 100K is 3000/1500). Both were deployed at the
                // wrong size by F-9 and are corrected here.
                //
                // The TYPE correction is the one that mattered: a TPT PRO account trails INTRADAY
                // until the buffer is hit, not EOD. An intraday trail follows peak equity including
                // unrealized, so its floor rises during a winning session while an EOD model's
                // stays stale and LOWER -- the firm's floor ends up above the guard's and the firm
                // fails you first, which is R3's stated failure mode. LockAtProfit = Amount encodes
                // "trails until the buffer is hit": the floor locks at the starting balance once
                // the peak reaches start + 2000.
                cfg.FirmMirror.FirmProfiles["TPT-50K-PRO"] = new FirmProfile
                {
                    Name = "TPT-50K-PRO",
                    AccountSize = 50000.0,
                    TrailingDD = new FirmTrailingDDConfig
                    {
                        Enabled = true, Type = "intraday", IncludesUnrealized = true,
                        Amount = 2000.0, Buffer = 200.0, LockAtProfit = 2000.0
                    },
                    // TPT has NO daily loss limit at any size or stage -- removed January 2025, so
                    // this is the firm's actual rule and not an omission. Enabled=false WITH
                    // Amount=0 is also the shape that matters for preflight: its "enabled but
                    // Amount <= 0" check must not fire on a sub-rule that is switched off, or a
                    // truthful profile cannot be armed.
                    DailyLoss = new FirmDailyLossConfig
                    {
                        Enabled = false, Basis = "realized", Amount = 0.0, Buffer = 0.0
                    }
                };
                cfg.FirmMirror.FirmProfiles["Apex-100K-EOD"] = new FirmProfile
                {
                    Name = "Apex-100K-EOD",
                    AccountSize = 100000.0,
                    // The key names the VARIANT because Apex sells two products at every size: an
                    // EOD one that HAS a daily loss limit and an intraday one that does not. Firm
                    // plus size is not a plan.
                    TrailingDD = new FirmTrailingDDConfig
                    {
                        Enabled = true, Type = "eod", IncludesUnrealized = false,
                        Amount = 3000.0, Buffer = 200.0, LockAtProfit = 0.0
                    },
                    // Realised basis, per the operator: every firm here is on realised except some
                    // Apex accounts, which are not yet identified.
                    DailyLoss = new FirmDailyLossConfig
                    {
                        Enabled = true, Basis = "realized", Amount = 1500.0, Buffer = 100.0
                    }
                };
                // The live funded account is mapped now that P2-92 is closed: before it, a shadow
                // breach set an enforced-looking lockout and stopped the account trading while
                // flattening nothing.
                cfg.FirmMirror.AccountFirmMap["TAKEPROFITPRO524207503"] = "TPT-50K-PRO";
                cfg.FirmMirror.AccountFirmMap["Sim_All_Day_ORB"] = "TPT-50K-PRO";
                cfg.FirmMirror.AccountFirmMap["Sim-ORB"] = "Apex-100K-EOD";
                cfg.FirmMirror.AccountFirmMap["Sim101"] = "Apex-100K-EOD";
                cfg.FirmMirror.AccountFirmMap["SimCopy2"] = "Apex-100K-EOD";
                cfg.FirmMirror.AccountFirmMap["SimCopyTest1"] = "Apex-100K-EOD";

                var addon = new RiskGuardAddOn();
                addon.SetConfigForTest(cfg);
                var result = addon.RunPreflight();

                Assert(result.Passed, string.Format(
                    "the deployed F-9 mapping passes preflight, so ARMED_ON_START still arms (got {0}: {1})",
                    result.FailureCode, result.FailureMessage));

                // The paired negative, so the assertion above cannot pass on a preflight that
                // approves anything. A plan key nothing defines is the typo this mapping is most
                // exposed to -- the account names alone are five chances to make one.
                var typo = new RiskConfig();
                typo.Mode = "shadow";
                typo.FirmMirror.Enabled = true;
                typo.FirmMirror.FirmProfiles["Apex-100K"] = new FirmProfile
                {
                    Name = "Apex-100K",
                    TrailingDD = new FirmTrailingDDConfig { Enabled = true, Amount = 2000.0, Buffer = 200.0 }
                };
                typo.FirmMirror.AccountFirmMap["Sim-ORB"] = "Apex-100k-typo";
                var typoAddon = new RiskGuardAddOn();
                typoAddon.SetConfigForTest(typo);
                var typoResult = typoAddon.RunPreflight();

                Assert(!typoResult.Passed
                       && typoResult.FailureMessage != null
                       && typoResult.FailureMessage.IndexOf("Apex-100k-typo", StringComparison.Ordinal) >= 0,
                    "a plan key nothing defines fails preflight AND the message names the key, so the "
                    + "operator knows which of the five mappings is wrong");
            }
            finally
            {
                Account.All = previousAccounts;
            }
        }

        // ================================================================================
        // F-9b -- the firm mapping has to be machine-checked, because it is hand-written.
        //
        // `F-9` put five accounts in `AccountFirmMap` on the live box. Two things about that map
        // are unverifiable by reading it, and both fail SILENTLY -- the account simply falls back
        // to the top-level block, which is deliberately disabled, so the result is no firm
        // protection and nothing saying so:
        //
        //   1. AN ACCOUNT NAME THAT DOES NOT EXIST. Five names is five chances at a typo, and the
        //      operator's own spelling of `Sim_All_Day_ORB` in the session that mapped it used a
        //      HYPHEN. `ResolveEffectiveFirmConfig` is OrdinalIgnoreCase but it cannot invent an
        //      account. This is `P1-90`'s class -- a name that does not resolve -- one layer out:
        //      there it placed an order on the wrong account, here it removes protection from the
        //      right one.
        //
        //   2. A PLAN WHOSE STATED SIZE CONTRADICTS THE ACCOUNT. `FirmProfiles` is keyed by plan
        //      (`Apex-100K`) precisely because one dollar amount cannot serve a 50k and a 100k,
        //      and the box holds both. Nothing checks that the account behind a `-100K` key is a
        //      100k account. Mapping a 50k account to a 100k plan puts the guard's floor BELOW the
        //      firm's own threshold, so the firm fails you before the guard speaks -- which is
        //      CONFIG_DEFAULTS R3's stated failure mode, in the direction that costs money.
        //
        // ⚠️ These tests deliberately go through `RunPreflight` and name no new symbol. Two
        // reasons. Preflight is where the existing firm-mirror validation already lives (`P2-8`
        // refuses to arm on a mapped firm that is absent from `FirmProfiles`), so it is the honest
        // home. And a test that named a new helper could be satisfied by exposing that helper
        // without ever calling it from anything -- which is `P1-77`'s shape, and this file's whole
        // subject.
        //
        // ⚠️ Preflight refusing is the fail-closed direction and it is also a real cost: the guard
        // does not arm, so there is no protection until the config is corrected. That is the right
        // trade only because the refusal NAMES the fix. Every assertion below therefore checks the
        // message content, not just the verdict.
        // ================================================================================

        /// <summary>
        /// Builds a config with one plan and one mapping, so each test varies exactly one thing.
        /// The plan's numbers are the recovered Apex research; only `AccountSize` and the mapped
        /// name change between tests.
        /// </summary>
        private static RiskConfig F9bConfig(string mappedAccount, string planKey, double planSize)
        {
            var cfg = new RiskConfig();
            cfg.Mode = "shadow";
            cfg.FirmMirror.Enabled = true;
            cfg.FirmMirror.TrailingDD.Enabled = false;
            cfg.FirmMirror.DailyLoss.Enabled = false;
            cfg.FirmMirror.FirmProfiles[planKey] = new FirmProfile
            {
                Name = planKey,
                AccountSize = planSize,
                TrailingDD = new FirmTrailingDDConfig
                {
                    Enabled = true, Type = "eod", IncludesUnrealized = false,
                    Amount = 2000.0, Buffer = 200.0
                },
                DailyLoss = new FirmDailyLossConfig
                {
                    Enabled = true, Basis = "include_unrealized_peak", Amount = 1000.0, Buffer = 100.0
                }
            };
            cfg.FirmMirror.AccountFirmMap[mappedAccount] = planKey;
            return cfg;
        }

        private static PreflightResultView F9bPreflight(RiskConfig cfg, params Account[] accounts)
        {
            var previous = Account.All;
            try
            {
                Account.All = accounts.ToList();
                var addon = new RiskGuardAddOn();
                addon.SetConfigForTest(cfg);
                addon.SetModeForTest(cfg.Mode);
                var r = addon.RunPreflight();
                return new PreflightResultView { Passed = r.Passed, Code = r.FailureCode, Message = r.FailureMessage };
            }
            finally { Account.All = previous; }
        }

        private class PreflightResultView
        {
            public bool Passed;
            public string Code;
            public string Message;
        }

        private static Account F9bAccount(string name, double cash)
        {
            var a = new Account { Name = name };
            a.Values[AccountItem.CashValue] = cash;
            a.Values[AccountItem.UnrealizedProfitLoss] = 0.0;
            a.Values[AccountItem.RealizedProfitLoss] = 0.0;
            return a;
        }

        /// <summary>
        /// A mapping to a name no account has must refuse to arm, and must NAME the name.
        /// Silently falling back is how `F-9` would deliver no protection while reading as
        /// configured -- the exact state `F-9` was built to end.
        /// </summary>
        private static void TestF9b_AMappingToAnAccountThatDoesNotExistFailsPreflight()
        {
            Console.WriteLine("\n[TEST] F-9b: a firm mapping naming an account that does not exist fails preflight");

            // The real typo: the live account is Sim_All_Day_ORB, with underscores.
            var typo = F9bConfig("Sim_All_Day-ORB", "Apex-100K", 100000.0);
            var bad = F9bPreflight(typo, F9bAccount("Sim_All_Day_ORB", 49833.70));

            Assert(!bad.Passed, "a mapping to a non-existent account refuses to arm");
            Console.WriteLine("        preflight said: " + (bad.Message ?? "<null>"));
            Assert(bad.Message != null
                   && bad.Message.IndexOf("Sim_All_Day-ORB", StringComparison.Ordinal) >= 0,
                "the refusal names the account that does not resolve, so the operator can see "
                + "WHICH of the mappings is wrong");

            // The paired positive: the same mapping, spelled correctly, arms. Without this, a
            // preflight that refused everything would pass the assertions above.
            var ok = F9bConfig("Sim_All_Day_ORB", "Apex-100K", 50000.0);
            var good = F9bPreflight(ok, F9bAccount("Sim_All_Day_ORB", 49833.70));
            Console.WriteLine(string.Format("        correctly-spelled: passed={0} {1} {2}",
                good.Passed, good.Code, good.Message));
            Assert(good.Passed, "the correctly-spelled mapping still arms");
        }

        /// <summary>
        /// A plan states the account size its dollar amounts came from. If the account behind it
        /// is a different size, the numbers are wrong in one direction or the other, and the
        /// dangerous direction is a floor BELOW the firm's own threshold.
        /// </summary>
        private static void TestF9b_APlanWhoseStatedSizeContradictsTheAccountFailsPreflight()
        {
            Console.WriteLine("\n[TEST] F-9b: a plan whose stated account size contradicts the account fails preflight");

            // A 100k account mapped to a plan researched for 50k.
            var wrong = F9bConfig("Sim-ORB", "TakeProfitTrader-50K", 50000.0);
            var bad = F9bPreflight(wrong, F9bAccount("Sim-ORB", 100170.0));

            Assert(!bad.Passed, "a 100k account mapped to a 50k plan refuses to arm");
            Console.WriteLine("        preflight said: " + (bad.Message ?? "<null>"));
            Assert(bad.Message != null
                   && bad.Message.IndexOf("TakeProfitTrader-50K", StringComparison.Ordinal) >= 0
                   && bad.Message.IndexOf("50000", StringComparison.Ordinal) >= 0
                   && bad.Message.IndexOf("100170", StringComparison.Ordinal) >= 0,
                "the refusal names the plan and BOTH numbers, because 'size mismatch' without them "
                + "is not actionable");

            // Ordinary drawdown is not a mismatch. A 50k account down 2,300 must still arm, or
            // this check fires on a normal week and gets switched off -- CONFIG_DEFAULTS R5.
            var drawn = F9bConfig("Sim_All_Day_ORB", "TakeProfitTrader-50K", 50000.0);
            var stillOk = F9bPreflight(drawn, F9bAccount("Sim_All_Day_ORB", 47700.0));
            Console.WriteLine(string.Format("        drawn-down 50k: passed={0} {1} {2}",
                stillOk.Passed, stillOk.Code, stillOk.Message));
            Assert(stillOk.Passed,
                "a 50k account drawn down to 47,700 is still a 50k account and still arms");
        }

        /// <summary>
        /// The two ways this check must NOT over-apply, paired in one test because they are the
        /// same mistake: treating "I cannot check this" as "this is wrong".
        ///
        /// An UNSTATED size (0) is not an error -- the check is opt-in per plan, or an operator
        /// adding a plan is locked out of arming until they have researched a number they may not
        /// have. And an account reporting ZERO equity cannot be size-checked at all: 89 of the 96
        /// accounts on the live box read zero because they are expired or unconnected, and
        /// refusing to arm over those would mean the guard never arms on that box again.
        ///
        /// ⚠️ But the EXISTENCE check still applies to a zero-equity account. It exists, so a
        /// mapping to it is legitimate; it is only its SIZE that is unknowable.
        /// </summary>
        private static void TestF9b_AnUnstatedSizeAndAnAbsentAccountAreDifferentThings()
        {
            Console.WriteLine("\n[TEST] F-9b: an unstated plan size and a zero-equity account are not errors; a missing account is");

            // (1) AccountSize = 0 means "not stated". Nothing to check, so nothing fails, even
            // though the equity is nowhere near any plausible plan size.
            var unstated = F9bConfig("Sim-ORB", "Apex-Unstated", 0.0);
            var r1 = F9bPreflight(unstated, F9bAccount("Sim-ORB", 100170.0));
            Console.WriteLine(string.Format("        unstated size: passed={0} {1} {2}", r1.Passed, r1.Code, r1.Message));
            Assert(r1.Passed, "a plan that states no account size is checked for nothing");

            // (2) A zero-equity account is real but unmeasurable. It must not fail the SIZE check.
            var expired = F9bConfig("APEX10121500000151", "Apex-100K", 100000.0);
            var r2 = F9bPreflight(expired,
                F9bAccount("APEX10121500000151", 0.0), F9bAccount("Sim101", 99482.0));
            Console.WriteLine(string.Format("        zero-equity: passed={0} {1} {2}", r2.Passed, r2.Code, r2.Message));
            Assert(r2.Passed,
                "an account reporting zero equity is not size-checked -- 89 of 96 on the live box read zero");

            // (3) ...but it is still EXISTENCE-checked. Remove it from the platform and the same
            // mapping must refuse. This is what stops (2) from being a hole big enough to swallow
            // the whole check.
            var r3 = F9bPreflight(expired, F9bAccount("Sim101", 99482.0));
            // (4) A NaN equity must not REFUSE TO ARM, and must not throw.
            //
            // ⚠️ READ THIS BEFORE TRUSTING THIS ASSERTION. `account.Get` can return NaN before a
            // provider has synced, and the review panel raised it: every comparison against NaN is
            // false, so `equity <= 0` does not skip it and `difference > 0.40` does not fail it --
            // a NaN slides through BOTH guards. The production code was changed to `!(equity > 0)`,
            // which skips NaN in the same operator instead of needing a second branch, and is more
            // robust to a later edit of the failure comparison.
            //
            // BUT THIS ASSERTION CANNOT SEE THAT CHANGE, and saying so is the point. Both forms
            // arrive at "preflight passed" for a NaN -- one by deliberate skip, one by falling
            // through two false comparisons -- so the boolean outcome is IDENTICAL and a test
            // asserting it would pass either way. Written as a claim about the skip it would be a
            // gate that cannot fail, which is the defect this file exists to catch.
            //
            // What it DOES pin, and this is a real property worth having: a NaN equity must not
            // make preflight FAIL. A plausible "defensive" implementation --
            // `if (double.IsNaN(equity)) result.Fail(...)` -- would leave the guard DISARMED because
            // one account had not synced yet, which is the 89-zero-accounts failure mode wearing a
            // different hat. It also pins that the arithmetic does not throw.
            var nanCfg = F9bConfig("Sim-ORB", "Apex-100K", 100000.0);
            var nanAcct = F9bAccount("Sim-ORB", 0.0);
            nanAcct.Values[AccountItem.CashValue] = double.NaN;
            var r4 = F9bPreflight(nanCfg, nanAcct);
            Console.WriteLine(string.Format("        NaN equity: passed={0} {1} {2}", r4.Passed, r4.Code, r4.Message));
            Assert(r4.Passed,
                "an account whose equity reads NaN does not refuse to arm -- an unsynced account "
                + "must not disarm the guard for every other account");

            Console.WriteLine("        absent account: " + (r3.Message ?? "<null>"));
            Assert(!r3.Passed
                   && r3.Message != null
                   && r3.Message.IndexOf("APEX10121500000151", StringComparison.Ordinal) >= 0,
                "a mapping to an account the platform does not report still refuses, even though "
                + "its size could never have been checked");
        }

        // ================================================================================
        // P2-92 -- `shadow` mode is not observation-only.
        //
        // `ProcessAction` gates EXECUTION on mode, so a shadow breach logs `SHADOW_ACTION` and
        // flattens nothing. That is the whole promise of the mode. But the rules set
        // `IsLockedOut` BEFORE dispatch, outside any mode check, and `CanTrade` reads that flag
        // ABOVE its own `if (!_isArmed) return true;` escape hatch. So in shadow: nothing is
        // flattened AND the account stops being allowed to trade. The copier consults
        // `CanTrade(followerName, ...)` and every strategy consults it through `RiskManagerBase`,
        // and the three refusal paths log to `Output.Process` only (P1-71) -- so nothing readable
        // says why a bot stood down.
        //
        // ⚠️ THE FIX IS NOT "MAKE CanTrade CONSULT THE MODE", and the tests below are arranged to
        // make that impossible to ship. A lockout imposed while the guard could ACT must keep
        // biting after the operator switches to shadow, or switching mode becomes a lockout
        // bypass -- which is FR-30 / judge-loop P1-4's exact concern wearing new clothes. What is
        // missing is the AUTHORITY under which a lockout was imposed, so that is what gets
        // recorded.
        //
        // ⚠️ AND THE SUITE HAS BEEN DEFENDING THIS DEFECT. Eight existing tests breach a rule in
        // the DEFAULT mode -- which is `shadow` -- and assert `state.IsLockedOut`. That is the
        // `P1-87` shape: a test asserting the defect as correct behaviour. They are left ALONE
        // here, deliberately: the state model is not the defect. `IsLockedOut` meaning "this
        // account has breached" is right, and the enforcement decision belongs to the consumer.
        // A fix that stopped writing the flag would have broken all eight and been indistinguish-
        // able, from the test output, from a fix that broke the guard.
        // ================================================================================

        /// <summary>
        /// Builds a guard with one account state registered, so `CanTrade` can see it.
        /// `EvaluatePnLRules` takes the state directly and does not register it.
        /// </summary>
        private static RiskGuardAddOn P292Guard(string mode, bool armed, out AccountState state, out Account account)
        {
            var cfg = new RiskConfig();
            cfg.Mode = mode;
            cfg.PnLRules.DailyLossLimit = 1000.0;
            cfg.PnLRules.LockoutMinutes = 60;

            var addon = new RiskGuardAddOn();
            addon.SetConfigForTest(cfg);
            addon.SetModeForTest(mode);
            addon.SetArmedForTest(armed);

            state = new AccountState("P292Acc");
            addon.SetAccountStateForTest("P292Acc", state);
            account = new Account { Name = "P292Acc" };
            return addon;
        }

        /// <summary>
        /// THE DEFECT. In shadow, a breach must not stop the account trading -- and the paired
        /// live case must still stop it, or this test passes on a guard that protects nothing.
        /// </summary>
        private static void TestP292_AShadowBreachMustNotStopTheAccountTrading()
        {
            Console.WriteLine("\n[TEST] P2-92: a breach in shadow mode does not stop the account trading");

            AccountState shadowState; Account shadowAcct;
            var shadow = P292Guard("shadow", true, out shadowState, out shadowAcct);
            shadowState.RealizedPnL = -1100.0;
            var shadowActions = shadow.EvaluatePnLRules(shadowAcct, shadowState);

            // The rule must still FIRE and still be recorded -- the point is that the shadow
            // observation is intact, not that the rule was switched off.
            Assert(shadowActions.Any(a => a.RuleId == "DAILY_LOSS_BREACH"),
                "precondition: the daily-loss rule still fires in shadow, and is still observed");

            Assert(shadow.CanTrade("P292Acc", "MNQ 03-26", "P292"),
                "a shadow-mode breach leaves the account TRADABLE: shadow gates execution, and a "
                + "lockout that stops the copier and every strategy is not an observation");

            AccountState liveState; Account liveAcct;
            var live = P292Guard("live", true, out liveState, out liveAcct);
            liveState.RealizedPnL = -1100.0;
            live.EvaluatePnLRules(liveAcct, liveState);

            Assert(!live.CanTrade("P292Acc", "MNQ 03-26", "P292"),
                "and the same breach in an ACTING mode still stops it, so the assertion above is "
                + "not passing on a guard that permits everything");
        }

        /// <summary>
        /// THE CLASS GATE, and it is a SOURCE ASSERTION -- it proves less than an execution would
        /// and must be labelled as such.
        ///
        /// Ten rule paths set `IsLockedOut`, spread over 2,800 lines: daily loss, trailing
        /// drawdown, the news shield, the evaluation target, the order-rate flood, per-instrument
        /// contracts, max trades, consecutive losses, and both firm-mirror rules. Fixing the one
        /// the acceptance test above drives would leave nine. Worse, a rule added LATER would
        /// reintroduce the defect with every test still green, which is how `P1-36` came to live
        /// in a second place.
        ///
        /// So every `IsLockedOut = true` in the addon must sit beside a write recording whether
        /// the guard could act, and the two sites that must NOT be gated are named explicitly
        /// rather than pattern-matched:
        ///   * the rehydration path -- a persisted lockout came from a real session
        ///   * `LockAccount` -- the operator asked for it, in whatever mode
        /// </summary>
        private static void TestP292_EveryRuleLockoutRecordsWhetherItCouldAct()
        {
            Console.WriteLine("\n[TEST] P2-92: every rule that locks out records whether it could act (SOURCE assertion)");

            var src = File.ReadAllText(AddonSourcePath()).Split('\n');

            // Sites the fix must NOT touch, matched on a nearby distinctive line rather than a
            // line number so this does not rot the moment the file shifts. Each one's HIT COUNT
            // is asserted below: `mutation/check_anchors.py` exists because a find-string that
            // stops matching scores its mutant a survivor in silence, and an exemption that stops
            // matching would quietly turn this gate into a demand that the two legitimate sites be
            // broken -- or, worse, exempt nothing and then everything.
            var exempt = new Dictionary<string, int>
            {
                { "state.LockoutUntil = DateTime.MinValue;", 0 },        // LockAccount, minutes == -1
                { "_accountStates[accName] = state;", 0 },               // rehydration from persisted state
            };

            // ⚠️ THIS GATE HAS TWO HALVES BECAUSE THE FIX REMOVES WHAT ITS FIRST DRAFT COUNTED,
            // and that mistake made T2 unpassable. The draft counted `IsLockedOut = true` sites
            // that had a `LockoutWasShadowOnly` write nearby -- which assumed the fix would add a
            // second assignment beside each of the ten. The spec instead routes them through one
            // helper, so a routed site contains NO `IsLockedOut = true` at all: after both tickets
            // the count would have been 1 (the helper) against a demand for 10, and the only way to
            // go green would have been to un-route the sites. A gate written before the shape of
            // the fix was decided will demand the shape it happened to imagine.
            //
            // So: NO non-exempt site may assign the flag directly (that is the invariant), AND at
            // least ten sites must call the helper (that is what makes a PARTIAL fix fail, which is
            // the whole reason this gate exists -- fixing only the path the behavioural test drives
            // is how P1-36 came to live in a second place).
            int gated = 0;
            var ungated = new List<string>();
            for (int i = 0; i < src.Length; i++)
            {
                if (src[i].IndexOf("IsLockedOut = true", StringComparison.Ordinal) < 0) continue;
                if (src[i].TrimStart().StartsWith("//", StringComparison.Ordinal)) continue;

                // A window either side, because the recording write may precede or follow.
                int lo = Math.Max(0, i - 6), hi = Math.Min(src.Length - 1, i + 6);
                string window = string.Join("\n", src.Skip(lo).Take(hi - lo + 1));

                var hit = exempt.Keys.FirstOrDefault(e => window.IndexOf(e, StringComparison.Ordinal) >= 0);
                if (hit != null) { exempt[hit] = exempt[hit] + 1; continue; }

                if (window.IndexOf("LockoutWasShadowOnly", StringComparison.Ordinal) >= 0) gated++;
                else ungated.Add("line " + (i + 1) + ": " + src[i].Trim());
            }

            // The helper's own call sites. Its DECLARATION is excluded by requiring a `(` that is
            // not preceded by `void ` / `private `, so declaring it ten times would not pass.
            int routed = src.Count(l =>
                l.IndexOf("MarkRuleLockout(", StringComparison.Ordinal) >= 0
                && l.IndexOf("private", StringComparison.Ordinal) < 0
                && !l.TrimStart().StartsWith("//", StringComparison.Ordinal));
            if (routed < 10)
                Console.WriteLine(string.Format("        only {0} site(s) call the helper; 10 rule paths lock out", routed));
            Assert(routed >= 10,
                "all ten rule-breach paths route their lockout through the one helper that records authority");

            var rotted = exempt.Where(kv => kv.Value != 1).Select(kv => kv.Key + " matched " + kv.Value).ToList();
            if (rotted.Count > 0)
                Console.WriteLine("        rotted exemptions: " + string.Join(" | ", rotted));
            Assert(rotted.Count == 0,
                "each exemption in this lockout gate still names exactly one site");

            // ⚠️ THE DETAIL GOES TO THE CONSOLE, NOT INTO THE ASSERTION MESSAGE, and this cost a
            // loop run to learn. The message started as "all {gated} sites ... ({n} do not: line
            // 1482 ...)". agent-loop matches an `expect_green` string ANYWHERE inside a failure
            // line, so volatile trailing detail is fine THERE -- but it also diffs the whole set of
            // failure lines against the baseline to find regressions. When T1 fixed two of the ten
            // sites, the counts and line numbers in this message changed, so the loop saw the old
            // line vanish (scored NEWLY PASSING) and a new line appear (scored a REGRESSION), on a
            // test that had simply moved from 0/10 to 2/10. A failure message is an IDENTIFIER for
            // baseline diffing and a DESCRIPTION for a human; when those two conflict, the
            // identifier wins and the description moves to stdout.
            if (ungated.Count > 0)
                Console.WriteLine(string.Format(
                    "        {0} site(s) record it, {1} do not: {2}",
                    gated, ungated.Count, string.Join(" | ", ungated)));
            Assert(gated >= 1 && ungated.Count == 0,
                "every rule-breach lockout site records whether the guard could act");
        }

        /// <summary>
        /// The wrong fix, made unshippable. GREEN AT BASELINE and must stay green.
        ///
        /// If `CanTrade` simply consulted the CURRENT mode, an operator who had been locked out in
        /// live could escape it by switching to shadow. FR-30 and judge-loop `P1-4` already
        /// settled that a panic toggle-off must not defeat a lockout; a mode switch is the same
        /// bypass through a different setting, and `LockoutBypassWhileDisarmedAccounts` cannot
        /// help because the guard is still armed.
        /// </summary>
        private static void TestP292_SwitchingToShadowIsNotALockoutBypass()
        {
            Console.WriteLine("\n[TEST] P2-92: a lockout imposed while ACTING survives a switch to shadow");

            AccountState state; Account account;
            var addon = P292Guard("live", true, out state, out account);
            state.RealizedPnL = -1100.0;
            addon.EvaluatePnLRules(account, state);
            Assert(!addon.CanTrade("P292Acc", "MNQ 03-26", "P292"),
                "precondition: the live-mode breach locked the account out");

            addon.SetModeForTest("shadow");
            Assert(!addon.CanTrade("P292Acc", "MNQ 03-26", "P292"),
                "switching to shadow does NOT release a lockout that was imposed while the guard "
                + "could act -- otherwise the mode setting is a one-click lockout bypass");
        }

        /// <summary>
        /// Fail closed on ABSENCE. GREEN AT BASELINE and must stay green.
        ///
        /// A state file written before this change records the lockout and says nothing about its
        /// authority. A `bool` deserialises absent as `false`, so the field is deliberately named
        /// for the SHADOW case -- `LockoutWasShadowOnly` -- and absence therefore reads as
        /// "enforced", which is the safe direction. `P1-54` reasoned exactly this way about
        /// `LockoutUntil`: an upgrade must not be able to shorten a lockout that was meant to hold.
        /// </summary>
        private static void TestP292_ALockoutFromAnOlderStateFileStillBites()
        {
            Console.WriteLine("\n[TEST] P2-92: a lockout from a state file that predates this change still bites");

            string path = Path.Combine(Path.GetTempPath(), "p292_legacy_state_" + Guid.NewGuid().ToString("N") + ".json");
            try
            {
                // Exactly the shape an older build wrote: the fact of the lockout, in the
                // top-level name list, and no authority field anywhere.
                File.WriteAllText(path,
                    "{\"IsArmed\":true,\"ShadowSessionsCompleted\":0,"
                    + "\"LockedOutAccounts\":[\"P292Legacy\"],"
                    + "\"AccountsData\":{\"P292Legacy\":{\"TradesToday\":3}},"
                    + "\"Timestamp\":\"2026-08-01T00:00:00Z\"}");

                var cfg = new RiskConfig();
                cfg.Mode = "shadow";
                var addon = new RiskGuardAddOn();
                addon.SetConfigForTest(cfg);
                addon.SetModeForTest("shadow");
                addon.SetArmedForTest(true);
                addon.SetStateFileForTest(path);
                addon.LoadPersistedStateForTest();

                var restored = addon.GetAccountStateForTest("P292Legacy");
                Assert(restored != null && restored.IsLockedOut,
                    "precondition: the legacy lockout was restored at all");
                Assert(!addon.CanTrade("P292Legacy", "MNQ 03-26", "P292"),
                    "a restored lockout with no recorded authority is treated as ENFORCED, because "
                    + "absence must fail closed -- an upgrade cannot be allowed to release a lockout");
            }
            finally
            {
                try { if (File.Exists(path)) File.Delete(path); } catch { }
            }
        }

        /// <summary>
        /// The over-application guard. GREEN AT BASELINE and must stay green.
        ///
        /// The cheapest way to pass the class gate is to gate EVERY `IsLockedOut = true`, which
        /// would make a lockout the operator asked for evaporate in shadow. `LockAccount` is an
        /// instruction, not a rule breach.
        /// </summary>
        private static void TestP292_AManualLockoutBitesInEveryMode()
        {
            Console.WriteLine("\n[TEST] P2-92: a lockout the operator asked for holds in shadow too");

            foreach (var mode in new[] { "shadow", "live" })
            {
                AccountState state; Account account;
                var addon = P292Guard(mode, true, out state, out account);
                addon.LockAccount("P292Acc", -1);
                Assert(!addon.CanTrade("P292Acc", "MNQ 03-26", "P292"), string.Format(
                    "a manual EOD lockout holds in {0} mode -- the operator asked for it, and the "
                    + "mode describes what the RULES may do, not what the operator may do", mode));
            }

            // ⚠️ AND IT MUST OVERRIDE A STALE SHADOW OBSERVATION. Raised by the review panel, and
            // it is a real hole rather than one of the four it invented: an account that breached
            // in shadow carries the lockout flag with shadow authority. If `LockAccount` then only
            // sets `IsLockedOut` -- which is already true -- the leftover authority stands and the
            // operator's instruction is silently ignored. The account was ALREADY in the state that
            // makes the bug reachable, which is what makes it easy to miss: the manual lockout
            // "succeeds" and changes nothing.
            AccountState stale; Account staleAcct;
            var shadowFirst = P292Guard("shadow", true, out stale, out staleAcct);
            stale.RealizedPnL = -1100.0;
            shadowFirst.EvaluatePnLRules(staleAcct, stale);
            Assert(shadowFirst.CanTrade("P292Acc", "MNQ 03-26", "P292"),
                "precondition: the shadow breach left the account tradable");

            shadowFirst.LockAccount("P292Acc", -1);
            Assert(!shadowFirst.CanTrade("P292Acc", "MNQ 03-26", "P292"),
                "a manual lockout on an account that already breached in SHADOW still bites -- the "
                + "operator's authority replaces the observation's, it does not inherit it");
        }

        /// <summary>
        /// A shadow lockout must be RECORDED, or `P2-92`'s fix is a deletion rather than a move.
        ///
        /// ⚠️ WRITTEN TO KILL THE LAST MUTATION SURVIVOR, and the survivor is the interesting part:
        /// deleting the `SHADOW_LOCKOUT` log line left all 1,224 tests green. Nothing in this suite
        /// could observe that an audit event happened at all, so every claim about this addon's log
        /// was pinned by a source scan or not at all -- including `P1-70`'s (a log must not claim an
        /// outcome it has not observed) and `P1-71`'s (a relationship that produced no order and left
        /// no diagnosable trace). `LogEventObserver` was added for this, under `#if TESTING`.
        ///
        /// What makes it matter rather than tidy: the whole point of shadow mode is to collect what
        /// the guard WOULD have done, and `MinShadowSessions` gates live arming on having done that.
        /// A shadow breach that stops the account trading was the defect. A shadow breach that
        /// records NOTHING is the defect's mirror image -- the observation is gone, and the operator
        /// has no way to learn that the rule would have fired.
        /// </summary>
        private static void TestP292_AShadowLockoutIsRECORDED()
        {
            Console.WriteLine("\n[TEST] P2-92: a shadow-mode lockout is recorded in the audit log, naming the rule");

            var seen = new List<string>();
            RiskGuardAddOn.LogEventObserver = (acct, evt) => seen.Add(acct + "/" + evt);
            try
            {
                AccountState state; Account account;
                var addon = P292Guard("shadow", true, out state, out account);
                state.RealizedPnL = -1100.0;
                addon.EvaluatePnLRules(account, state);

                Console.WriteLine("        events: " + string.Join(", ", seen));
                Assert(seen.Any(e => e == "P292Acc/SHADOW_LOCKOUT"),
                    "a shadow-mode breach emits SHADOW_LOCKOUT for that account, so the shadow "
                    + "session MinShadowSessions gates on has something in it");

                // The paired negative: an ACTING breach must not report itself as a shadow
                // observation, or the shadow session's count is inflated by real lockouts.
                seen.Clear();
                AccountState liveState; Account liveAcct;
                var live = P292Guard("live", true, out liveState, out liveAcct);
                liveState.RealizedPnL = -1100.0;
                live.EvaluatePnLRules(liveAcct, liveState);
                Assert(!seen.Any(e => e.EndsWith("/SHADOW_LOCKOUT", StringComparison.Ordinal)),
                    "and an ACTING-mode breach emits no SHADOW_LOCKOUT, so the shadow record is not "
                    + "inflated by lockouts that really fired");
            }
            finally
            {
                RiskGuardAddOn.LogEventObserver = null;
            }
        }

        /// <summary>
        /// The authority must SURVIVE a restart, in both directions.
        ///
        /// ⚠️ WRITTEN TO KILL TWO MUTATION SURVIVORS, and they survived for the same reason: both
        /// fail CLOSED, so nothing about the guard's behaviour looked wrong. Deleting the write to
        /// the persisted DTO, or the read back out of it, leaves every restored lockout reading as
        /// ENFORCED. On a funded account that is the safe direction and it is still wrong: a
        /// restart PROMOTES a shadow observation into a real lockout, so the account stops trading
        /// for a breach that never enforced, with no breach in the current session to point at. A
        /// phantom lockout is exactly the kind of thing that gets the whole system switched off.
        ///
        /// A recompile is a restart here (`P1-54` says so about `LockoutUntil`), so this is not an
        /// edge case — it is what happens the next time anyone touches the addon.
        ///
        /// Both directions are asserted, because "always restore as shadow-only" would pass the
        /// first half while removing protection from a real lockout.
        /// </summary>
        private static void TestP292_TheAuthoritySurvivesASaveLoadRoundTrip()
        {
            Console.WriteLine("\n[TEST] P2-92: a lockout's authority survives a save/load round trip, in both directions");

            foreach (var mode in new[] { "shadow", "live" })
            {
                string path = Path.Combine(Path.GetTempPath(),
                    "p292_roundtrip_" + mode + "_" + Guid.NewGuid().ToString("N") + ".json");
                try
                {
                    AccountState state; Account account;
                    var before = P292Guard(mode, true, out state, out account);
                    before.SetStateFileForTest(path);
                    state.RealizedPnL = -1100.0;
                    before.EvaluatePnLRules(account, state);
                    Assert(state.IsLockedOut, string.Format(
                        "precondition: the {0}-mode breach recorded a lockout", mode));
                    before.SavePersistedStateForTest();

                    var cfg = new RiskConfig();
                    cfg.Mode = mode;
                    var after = new RiskGuardAddOn();
                    after.SetConfigForTest(cfg);
                    after.SetModeForTest(mode);
                    after.SetArmedForTest(true);
                    after.SetStateFileForTest(path);
                    after.LoadPersistedStateForTest();

                    var restored = after.GetAccountStateForTest("P292Acc");
                    Assert(restored != null && restored.IsLockedOut, string.Format(
                        "the lockout itself survives the round trip in {0} mode", mode));

                    bool canTrade = after.CanTrade("P292Acc", "MNQ 03-26", "P292");
                    if (mode == "shadow")
                        Assert(canTrade,
                            "a SHADOW lockout is still shadow-only after a restart -- a recompile "
                            + "must not promote an observation into an enforced lockout");
                    else
                        Assert(!canTrade,
                            "a LIVE lockout is still enforced after a restart -- a restart must not "
                            + "release a lockout that was imposed while the guard could act");
                }
                finally
                {
                    try { if (File.Exists(path)) File.Delete(path); } catch { }
                }
            }
        }

        /// <summary>
        /// A dictionary ENTRY whose value is null is not a resolved plan.
        ///
        /// `ResolveEffectiveFirmConfig` falls back when `TryGetValue` succeeds but the profile is
        /// null -- it tests `out profile` for null explicitly. An evaluator that asks the same
        /// question with `ContainsKey` gets `true`, and then says "resolved to plan 'X'; its numbers
        /// are in force" while the numbers actually in force are the top-level block's. That is a
        /// note contradicting the enforcer, which is the whole defect F-9 closes, in the one shape
        /// where the two lookups can disagree.
        ///
        /// Found by hand while arbitrating the loop's candidate, which used `ContainsKey`. Json.NET
        /// produces exactly this shape from `"FirmProfiles": { "Apex-100K": null }` -- a typo away
        /// from a real config file.
        /// </summary>
        private static void TestF9_ADictionaryEntryHoldingNullIsNotAResolvedPlan()
        {
            Console.WriteLine("\n[TEST] F-9: a FirmProfiles entry whose value is null is not a resolved plan");

            // Top-level ENABLED, so the fallback the resolver takes is a rule that evaluates --
            // otherwise the row would come back Disabled and prove nothing about the note.
            var fm = F9Config(new F9Shape
            {
                MasterEnabled = true, TopLevelEnabled = true,
                ProfilePresent = true, ProfileEnabled = true, Mapped = true
            }, true);
            fm.FirmProfiles[F9Plan] = null;

            GuardRuleReading reading;
            var state = F9ReporterState(fm, F9Account, "FirmMirror.TrailingDD.Amount", out reading);

            // The numbers in force are the top-level 2500, and the note must not claim otherwise.
            Assert(state != GuardRuleState.Disabled
                   && reading != null && reading.Limit.HasValue
                   && Math.Abs(reading.Limit.Value - 2500.0) < 0.001,
                string.Format("a null profile falls back to the top-level 2500, as the resolver does (got {0}, state {1})",
                    reading == null || !reading.Limit.HasValue ? "null" : reading.Limit.Value.ToString(), state));

            Assert(reading != null && !string.IsNullOrEmpty(reading.Note)
                   && reading.Note.IndexOf("resolved to plan", StringComparison.OrdinalIgnoreCase) < 0,
                "the note must NOT claim the plan resolved, because the resolver did not resolve it: "
                + (reading == null ? "null" : "'" + reading.Note + "'"));

            // Paired positive, so "never say resolved" cannot pass this test on its own.
            var good = F9Config(new F9Shape
            {
                MasterEnabled = true, TopLevelEnabled = true,
                ProfilePresent = true, ProfileEnabled = true, Mapped = true
            }, true);
            GuardRuleReading goodReading;
            F9ReporterState(good, F9Account, "FirmMirror.TrailingDD.Amount", out goodReading);
            Assert(goodReading != null && !string.IsNullOrEmpty(goodReading.Note)
                   && goodReading.Note.IndexOf("resolved to plan", StringComparison.OrdinalIgnoreCase) >= 0,
                "a genuinely resolved plan still says so");
        }

        // 3. Firm Mirror Daily Loss Integration
        private static void TestFirmMirrorDailyLossBreachEmitsAction()
        {
            Console.WriteLine("\n[TEST] Firm Mirror Daily Loss Breach Emits Action And Locks Out");
            var account = new Account { Name = "FirmAcc" };
            var addon = new RiskGuardAddOn();
            
            var fmConfig = new FirmMirrorConfig();
            fmConfig.Enabled = true;
            fmConfig.DailyLoss.Enabled = true;
            fmConfig.DailyLoss.Amount = 1500;
            fmConfig.DailyLoss.Buffer = 200; // Limit is -1300
            
            var config = new RiskConfig();
            config.FirmMirror = fmConfig;
            addon.SetConfigForTest(config);
            
            var state = new AccountState("FirmAcc");
            // Fixed clock, and FirmDailyDate derived with the SAME boundary rule the production
            // code uses. Previously this set UtcNow.Date, which stops matching after 22:00 UTC
            // and silently rebased FirmDailyStartRealized, so the breach never fired.
            var nowUtc = FirmTestClockUtc;
            state.FirmDailyDate = FirmDailyDateFor(nowUtc, fmConfig);
            state.FirmDailyStartRealized = 0.0;
            
            account.Values[AccountItem.RealizedProfitLoss] = -1400.0; // Less than limit -1300
            account.Values[AccountItem.UnrealizedProfitLoss] = 0.0;
            account.Values[AccountItem.CashValue] = 98600.0; 

            var actions = addon.EvaluateFirmMirror(account, state, nowUtc);
            
            Assert(actions.Any(a => a.RuleId == "FIRM_DAILY_LOSS_BREACH"), "Firm daily loss breach action generated");
            Assert(state.IsLockedOut == true, "Firm mirror breach locks out account");
        }

