        private static void TestCM3_AnUnrelatedEditDoesNotSilentlyDisarm()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM3: an edit that never mentions arming leaves the armed state as it was");

            // The counterpart to the test above, and the reason merge semantics
            // need saying out loud here: if an omitted armedForLive fell back to
            // the initialiser's false, then nudging a ratio would silently stop a
            // live group from copying -- the leader trades and the follower does
            // not, which is P0-9's failure shape arrived at from a new direction.
            var engine = Cm3EngineWithAStoredGroup();
            engine.ApplyGroupRequest(JObject.Parse(
                @"{""groupName"":""Cm3Group"",""armedForLive"":true}"), true);

            var merged = engine.ApplyGroupRequest(JObject.Parse(
                @"{""groupName"":""Cm3Group"",""quantityRatio"":3.0}"), false);

            Assert(merged != null && merged.ArmedForLive == true,
                "a partial edit that never mentions armedForLive left it armed");
            Assert(merged != null && merged.QuantityRatio == 3.0, "and still applied the edit");

            var disarmed = engine.ApplyGroupRequest(JObject.Parse(
                @"{""groupName"":""Cm3Group"",""armedForLive"":false}"), false);
            Assert(disarmed != null && disarmed.ArmedForLive == false,
                "an EXPLICIT armedForLive:false disarms without needing confirmLive");
        }

        private static void TestCM3_AMalformedRequestDoesNotDestroyTheStoredGroup()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM3: an unreadable request field leaves the stored config untouched");

            // Session 14's rule, applied to the write path: a malformed NUMBER
            // fails closed. It must not land a zero cap, and it must not take the
            // stored matrix with it on the way out.
            var engine = Cm3EngineWithAStoredGroup();
            CopierGroup merged = null;
            try
            {
                // The VALID field first, then the malformed one. That ordering is
                // the whole test: merging populates in document order, so if the
                // merge writes onto the stored object instead of a copy, the
                // ratio lands, the cap throws, and the group is left in a state
                // the caller never asked for and no longer knows about.
                // A mutation removing the defensive clone survives without this.
                merged = engine.ApplyGroupRequest(JObject.Parse(
                    @"{""groupName"":""Cm3Group"",""quantityRatio"":9.0,""maxPositionSize"":""not-a-number""}"), false);
            }
            catch (Exception) { merged = null; }

            var stored = engine.GetGroups().FirstOrDefault(g => g.GroupName == "Cm3Group");
            Assert(stored != null, "the stored group still exists after a malformed request");
            Assert(stored == null || stored.MaxPositionSize == 42, string.Format(
                "the malformed number neither applied nor became a zero cap (got {0})",
                stored == null ? -1 : stored.MaxPositionSize));
            Assert(stored == null || stored.QuantityRatio == 1.0, string.Format(
                "the request applied ALL OR NOTHING -- the valid field did not land on its own (got {0})",
                stored == null ? -1.0 : stored.QuantityRatio));
            Assert(stored == null || (stored.PerTickerRatios != null && stored.PerTickerRatios.Count == 2),
                "the stored matrix survived the malformed request");
            Assert(merged == null || merged.MaxPositionSize != 0,
                "no zero position cap was returned");
        }

        private static void TestCM3_AnUnknownEnumFallsBackRatherThanRefusingTheRequest()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM3: an unrecognised sizingMode leaves the stored one and does not sink the request");

            // Session 14's settled rule, on the write path: a malformed ENUM falls
            // back rather than failing, while a malformed NUMBER fails closed.
            // Tolerating an unknown enum name is not tolerating every error.
            // Here "falls back" means "keeps what was stored", and the rest of the
            // request must still apply -- otherwise one stale UI dropdown value
            // would silently refuse every edit the caller makes alongside it.
            var engine = Cm3EngineWithAStoredGroup();
            CopierGroup merged = null;
            try
            {
                merged = engine.ApplyGroupRequest(JObject.Parse(
                    @"{""groupName"":""Cm3Group"",""sizingMode"":""NotARealMode"",""quantityRatio"":6.0}"), false);
            }
            catch (Exception ex)
            {
                Assert(false, "an unknown enum name did not throw (got " + ex.GetType().Name + ")");
            }

            Assert(merged != null && merged.SizingMode == CopierSizingMode.PerTickerMatrix, string.Format(
                "the stored SizingMode survived an unrecognised one (got {0})",
                merged == null ? "<refused>" : merged.SizingMode.ToString()));
            Assert(merged != null && merged.QuantityRatio == 6.0, string.Format(
                "the rest of the request still applied (got {0})",
                merged == null ? -1.0 : merged.QuantityRatio));
        }

        // ------------------------------------------------------------------
        // CM4: slice 2 -- cross-instrument ratio rules (1 MNQ -> 3 MES)
        //
        // Slice 1 shipped PerTickerMatrix as SAME-INSTRUMENT ONLY and refused a
        // CustomSymbolMappings entry naming a different root. Slice 2 implements
        // that case, so the refusal is REPLACED, not supplemented -- the CM1 test
        // that pinned it has been rewritten to the opposite expectation.
        //
        // ONE RULE IS (leader root -> follower root, ratio), and BOTH halves are
        // keyed by the LEADER root:
        //
        //     CustomSymbolMappings["MNQ"] = "MES"   <- where it goes
        //     PerTickerRatios["MNQ"]      = 3.0     <- how many
        //
        // Keying them the same way is the whole point. Slice 1's defect 2 was the
        // instrument decision and the quantity decision being made in two places
        // from two different keys, which routed an MES leader fill to ES while
        // sizing it in MES contracts. A rule keyed by the follower root on one
        // side and the leader root on the other would reintroduce exactly that.
        //
        // P1-22's rule survives and is asserted here: MNQ and MES do not share a
        // price scale, so a cross-instrument copy records NO slippage and mirrors
        // NO bracket. ES -> MES is a different case -- same underlying, same
        // scale -- and stays comparable.
        //
        // Written BEFORE the fix; every Assert below is expected to FAIL at
        // baseline. In this file rather than a new one because Program is not
        // partial and Assert is private to it (see the CM1 header).
        // ------------------------------------------------------------------

        private static CopierRelationship Cm4Cross(double ratio, string leaderRoot = "MNQ", string followerRoot = "MES")
        {
            var rel = new CopierRelationship
            {
                LeaderAccountName = "Cm4Leader",
                FollowerAccountName = "Cm4Follower",
                SizingMode = CopierSizingMode.PerTickerMatrix,
                QuantityRatio = 7.0,          // must be ignored
                AutoSymbolConversion = true,
                MaxPositionSize = 100
            };
            rel.CustomSymbolMappings[leaderRoot] = followerRoot;
            rel.PerTickerRatios[leaderRoot] = ratio;
            return rel;
        }

        private static void TestCM4_OneRuleDecidesBothTheInstrumentAndTheCount()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM4: 1 MNQ -> 3 MES sizes AND routes from a single rule");

            var engine = new TradeCopierEngine();
            var rel = Cm4Cross(3.0);

            bool clamped;
            int qty = engine.CalculateFollowerQuantity(rel, 1, "MNQ 03-26", 0, false, out clamped);
            Assert(qty == 3 && !clamped, string.Format(
                "one MNQ lot sized three MES contracts (got {0}, clamped {1})", qty, clamped));

            string translated = engine.TranslateSymbol("MNQ 03-26", rel);
            Assert(translated == "MES 03-26", string.Format(
                "the same rule routed the copy to MES (got '{0}')", translated));

            // The count is a literal contract count in the FOLLOWER's instrument,
            // with no mini/micro multiplier -- the rule settled in slice 1. If the
            // symbol multiplier leaked back in, 3 would become 0 or 30.
            bool clampedFive;
            int five = engine.CalculateFollowerQuantity(Cm4Cross(5.0), 2, "MNQ 03-26", 0, false, out clampedFive);
            Assert(five == 10, string.Format(
                "two lots at a ratio of 5 sized ten, with no symbol multiplier (got {0})", five));

            // And the flat QuantityRatio of 7.0 on the relationship stays ignored.
            Assert(qty != 7, "matrix mode still ignored the flat QuantityRatio");
        }

        private static void TestCM4_TheRatioIsKeyedByTheLeaderRootNotTheFollower()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM4: a ratio keyed by the FOLLOWER root is not a rule, and fails closed");

            // The trap this pins: an operator writes the mapping MNQ -> MES and
            // then keys the ratio by MES, because that is the contract they are
            // buying. There is then no rule for MNQ. Guessing -- looking the ratio
            // up under the mapped root as a fallback -- is exactly slice 1's
            // defect 2, two keys for one decision. Refuse instead.
            var engine = new TradeCopierEngine();
            var rel = new CopierRelationship
            {
                LeaderAccountName = "Cm4Leader",
                FollowerAccountName = "Cm4Follower",
                SizingMode = CopierSizingMode.PerTickerMatrix,
                QuantityRatio = 7.0,
                AutoSymbolConversion = true,
                MaxPositionSize = 100
            };
            rel.CustomSymbolMappings["MNQ"] = "MES";
            rel.PerTickerRatios["MES"] = 3.0;      // WRONG key: the follower root

            bool clamped;
            int qty = engine.CalculateFollowerQuantity(rel, 1, "MNQ 03-26", 0, false, out clamped);
            Assert(qty == 0 && clamped, string.Format(
                "an entry with no rule for the LEADER root was refused, not sized off the follower key (got {0}, clamped {1})",
                qty, clamped));

            // Exits are never refused -- the copier fails closed on entries only.
            bool exitClamped;
            int exitQty = engine.CalculateFollowerQuantity(rel, 1, "MNQ 03-26", 5, true, out exitClamped);
            Assert(exitQty > 0, string.Format(
                "the matching exit still copied rather than stranding the follower (got {0})", exitQty));
        }

        private static void TestCM4_ACrossMappingWithNoRatioAtAllFailsClosed()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM4: a mapping without a ratio is half a rule, and is refused on entry");

            var engine = new TradeCopierEngine();
            var rel = new CopierRelationship
            {
                LeaderAccountName = "Cm4Leader",
                FollowerAccountName = "Cm4Follower",
                SizingMode = CopierSizingMode.PerTickerMatrix,
                QuantityRatio = 7.0,
                AutoSymbolConversion = true,
                MaxPositionSize = 100
            };
            rel.CustomSymbolMappings["MNQ"] = "MES";   // no PerTickerRatios entry

            bool clamped;
            int qty = engine.CalculateFollowerQuantity(rel, 1, "MNQ 03-26", 0, false, out clamped);
            Assert(qty == 0 && clamped, string.Format(
                "a cross mapping with no ratio was refused rather than copied unscaled (got {0}, clamped {1})",
                qty, clamped));

            bool exitClamped;
            int exitQty = engine.CalculateFollowerQuantity(rel, 1, "MNQ 03-26", 5, true, out exitClamped);
            Assert(exitQty > 0, string.Format(
                "the exit still copied (got {0})", exitQty));
        }

        private static void TestCM4_AnInvalidCrossInstrumentRatioIsStillNoRule()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM4: slice 1's ratio validation still applies across instruments");

            // A negative ratio is a REFUSAL, not an absolute value. Slice 1 pinned
            // this for same-instrument rules; crossing instruments must not have
            // opened a second, laxer path to the same lookup.
            var engine = new TradeCopierEngine();

            foreach (double bad in new[] { -3.0, 0.0, double.NaN, double.PositiveInfinity, double.NegativeInfinity })
            {
                bool clamped;
                int qty = engine.CalculateFollowerQuantity(
                    Cm4Cross(bad), 1, "MNQ 03-26", 0, false, out clamped);
                Assert(qty == 0 && clamped, string.Format(
                    "a cross-instrument ratio of {0} was treated as no rule (got {1}, clamped {2})",
                    bad, qty, clamped));
            }

            // And one that rounds to zero is still a refusal rather than a silent skip.
            bool roundClamped;
            int roundQty = engine.CalculateFollowerQuantity(
                Cm4Cross(0.4), 1, "MNQ 03-26", 0, false, out roundClamped);
            Assert(roundQty == 0 && roundClamped,
                "a cross-instrument ratio rounding to zero was refused, not silently skipped");
        }

        private static void TestCM4_TheInstrumentDecisionIsMadeInExactlyOnePlace()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM4: bracket mirroring resolves the follower instrument the same way the copy does");

            // ResolveFollowerInstrument short-circuited on AutoSymbolConversion
            // BEFORE consulting the mapping, while TranslateSymbol -- which the
            // actual copy uses -- honours an explicit mapping regardless. With
            // AutoSymbolConversion off and a cross mapping set, the copy went to
            // MES while the bracket was computed against MNQ, and
            // ArePricesComparable(MNQ, MNQ) is true, so a leader stop distance in
            // MNQ points would have been mirrored onto an MES position as a
            // FABRICATED risk level. That is the exact hazard P1-22's guard exists
            // to prevent, reached by making the two decisions in two places.
            var engine = new TradeCopierEngine();
            var rel = Cm4Cross(3.0);
            rel.AutoSymbolConversion = false;

            var leaderInstrument = new Instrument("MNQ 03-26");
            var resolved = engine.ResolveFollowerInstrument(rel, leaderInstrument);
            string translated = engine.TranslateSymbol("MNQ 03-26", rel);

            Assert(resolved != null, "the follower instrument resolved");
            Assert(resolved != null && resolved.FullName == translated, string.Format(
                "both paths named the same follower instrument (bracket '{0}' vs copy '{1}')",
                resolved == null ? "null" : resolved.FullName, translated));
            Assert(resolved != null && resolved.FullName == "MES 03-26", string.Format(
                "an explicit mapping is honoured even with AutoSymbolConversion off (got '{0}')",
                resolved == null ? "null" : resolved.FullName));
        }

        private static void TestCM4_IncomparableRootsRecordNoSlippageAndNoBracket()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM4: P1-22 survives -- MNQ and MES do not share a price scale");

            // The whole reason cross-instrument copies are special. A fill price
            // difference between MNQ and MES is not slippage, it is two different
            // products; recording it would quarantine a healthy relationship, and
            // mirroring a stop distance across it would invent a risk level.
            Assert(!TradeCopierEngine.ArePricesComparable("MNQ", "MES"),
                "MNQ -> MES is NOT price comparable, so it records no slippage and mirrors no bracket");
            Assert(!TradeCopierEngine.ArePricesComparable("MES", "MNQ"),
                "and the same holds in the other direction");

            // ES -> MES is a different case: same underlying, same price scale.
            // Slice 2 must not have made every cross-instrument pair incomparable.
            Assert(TradeCopierEngine.ArePricesComparable("ES", "MES"),
                "ES -> MES stays comparable: same underlying at the same scale");
            Assert(TradeCopierEngine.ArePricesComparable("MNQ", "MNQ"),
                "a same-root copy stays comparable");
            Assert(!TradeCopierEngine.ArePricesComparable("CL", "MES"),
                "two unrelated roots are not comparable");
        }

        private static void TestCM4_MatrixStillNeverAutoConverts()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM4: crossing instruments still takes an EXPLICIT mapping, never the auto table");

            // Slice 1's rule, and the reason slice 2 is safe: matrix mode does not
            // consult the mini/micro auto table at all. If it did, every MNQ copy
            // would silently become NQ and the operator's table would be sizing
            // one instrument while the order went to another.
            var engine = new TradeCopierEngine();
            var rel = Cm1Matrix(3.0, "MNQ");   // ratio only, no CustomSymbolMappings

            string translated = engine.TranslateSymbol("MNQ 03-26", rel);
            Assert(translated == "MNQ 03-26", string.Format(
                "matrix mode left MNQ alone instead of auto converting it to NQ (got '{0}')", translated));

            bool clamped;
            int qty = engine.CalculateFollowerQuantity(rel, 1, "MNQ 03-26", 0, false, out clamped);
            Assert(qty == 3 && !clamped, string.Format(
                "and it still sized the same-instrument rule from the table (got {0})", qty));
        }

        // ------------------------------------------------------------------
        // CM5: a collection named in the request REPLACES the stored one
        //
        // Found on the sim accounts, not in the suite. Slice 3b's merge fixed
        // "a partial update destroys everything", and introduced the opposite
        // defect: JsonConvert.PopulateObject reuses the EXISTING dictionary
        // instance (that is what preserves the OrdinalIgnoreCase comparer, and
        // why P1-39 forbids ObjectCreationHandling.Replace) and merges keys INTO
        // it. It never removes one.
        //
        // So the matrix became append-only. Live:
        //
        //     PerTickerRatios = {"MNQ": 3.0}
        //     set perTickerRatios = {}        -> still {"MNQ": 3.0}
        //
        // An operator could not remove a ticker rule, could not fix a typo'd
        // mapping, and could not empty the table -- the only way out was to
        // delete the whole relationship and rebuild it. A ratio table you can
        // only add to is not a usable config surface.
        //
        // The rule: ABSENT or null means "unchanged" (slice 3b, unchanged here).
        // PRESENT means "this is now the value", including when it is empty.
        // The collection object itself is kept and cleared rather than replaced,
        // so the comparer survives.
        //
        // Written BEFORE the fix; every Assert below is expected to FAIL at
        // baseline. In this file rather than a new one because Program is not
        // partial and Assert is private to it (see the CM1 header).
        // ------------------------------------------------------------------

        private static void TestCM5_AnEmptyCollectionInTheRequestClearsTheStoredOne()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM5: sending an empty matrix clears it instead of being a no-op");

            var engine = Cm3EngineWithAStoredGroup();
            var merged = engine.ApplyGroupRequest(JObject.Parse(
                @"{""groupName"":""Cm3Group"",""perTickerRatios"":{}}"), false);

            Assert(merged != null && merged.PerTickerRatios != null && merged.PerTickerRatios.Count == 0,
                string.Format("an explicitly empty matrix emptied the stored one (got {0} entries)",
                    merged == null || merged.PerTickerRatios == null ? -1 : merged.PerTickerRatios.Count));

            // Only what was NAMED is replaced. Slice 3b's guarantee still holds
            // for everything else in the same request.
            Assert(merged != null && merged.CustomSymbolMappings != null && merged.CustomSymbolMappings.Count == 1,
                "the mappings, which the request never mentioned, were left alone");
            Assert(merged != null && merged.MaxPositionSize == 42,
                "and so was every other unmentioned field");
        }

        private static void TestCM5_APresentCollectionReplacesRatherThanAccumulates()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM5: a matrix in the request is the whole matrix, not an addition to it");

            var engine = Cm3EngineWithAStoredGroup();   // MES=3.0, MNQ=5.0
            var merged = engine.ApplyGroupRequest(JObject.Parse(
                @"{""groupName"":""Cm3Group"",""perTickerRatios"":{""MES"":9.0}}"), false);

            Assert(merged != null && merged.PerTickerRatios != null && merged.PerTickerRatios.Count == 1,
                string.Format("the table is exactly what was sent, not the union (got {0} entries)",
                    merged == null || merged.PerTickerRatios == null ? -1 : merged.PerTickerRatios.Count));
            double mes = 0.0;
            Assert(merged != null && merged.PerTickerRatios != null
                   && merged.PerTickerRatios.TryGetValue("MES", out mes) && mes == 9.0,
                "the value sent was applied");
            Assert(merged != null && merged.PerTickerRatios != null
                   && !merged.PerTickerRatios.ContainsKey("MNQ"),
                "the rule that was NOT resent is gone -- this is how a ticker gets removed");
        }

        private static void TestCM5_ReplacingAMatrixKeepsItCaseInsensitive()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM5: the replaced matrix is still an OrdinalIgnoreCase dictionary");

            // The reason the collection is CLEARED rather than reassigned. A new
            // Dictionary<string,double> would default to the ordinal comparer and
            // a fill on "mes" would miss the "MES" rule just configured -- P1-39's
            // trap, reached from the write path.
            var engine = Cm3EngineWithAStoredGroup();
            var merged = engine.ApplyGroupRequest(JObject.Parse(
                @"{""groupName"":""Cm3Group"",""perTickerRatios"":{""MES"":9.0},""customSymbolMappings"":{""NQ"":""MNQ""}}"),
                false);

            double v = 0.0;
            Assert(merged != null && merged.PerTickerRatios != null
                   && merged.PerTickerRatios.TryGetValue("mes", out v) && v == 9.0,
                "the replaced ratio table is OrdinalIgnoreCase");
            string mapped = null;
            Assert(merged != null && merged.CustomSymbolMappings != null
                   && merged.CustomSymbolMappings.TryGetValue("nq", out mapped) && mapped == "MNQ",
                "the replaced mapping table is OrdinalIgnoreCase");
        }

        private static void TestCM5_AnAbsentOrNullCollectionIsStillUnchanged()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM5: absent and null still mean \"unchanged\" -- slice 3b is not undone");

            var engine = Cm3EngineWithAStoredGroup();

            var absent = engine.ApplyGroupRequest(JObject.Parse(
                @"{""groupName"":""Cm3Group"",""quantityRatio"":2.0}"), false);
            Assert(absent != null && absent.PerTickerRatios != null && absent.PerTickerRatios.Count == 2,
                "an ABSENT matrix left the stored one alone");

            var nulled = engine.ApplyGroupRequest(JObject.Parse(
                @"{""groupName"":""Cm3Group"",""perTickerRatios"":null}"), false);
            Assert(nulled != null && nulled.PerTickerRatios != null && nulled.PerTickerRatios.Count == 2,
                "a NULL matrix left the stored one alone");
        }

        private static void TestCM5_TheFollowerListIsReplaceableToo()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM5: the same rule applies to list-valued fields, not just dictionaries");

            var engine = Cm3EngineWithAStoredGroup();   // FollowerAccounts = [Cm3Follower]

            var replaced = engine.ApplyGroupRequest(JObject.Parse(
                @"{""groupName"":""Cm3Group"",""followers"":[""A"",""B""]}"), false);
            Assert(replaced != null && replaced.FollowerAccounts != null && replaced.FollowerAccounts.Count == 2,
                string.Format("the follower list is exactly what was sent (got {0})",
                    replaced == null || replaced.FollowerAccounts == null ? -1 : replaced.FollowerAccounts.Count));
            Assert(replaced != null && replaced.FollowerAccounts != null
                   && !replaced.FollowerAccounts.Contains("Cm3Follower"),
                "the follower that was not resent is gone -- this is how one is removed");

            var emptied = engine.ApplyGroupRequest(JObject.Parse(
                @"{""groupName"":""Cm3Group"",""followerAccounts"":[]}"), false);
            Assert(emptied != null && emptied.FollowerAccounts != null && emptied.FollowerAccounts.Count == 0,
                "an explicitly empty follower list empties it");
        }

        private static void TestCM5_ReplacementAppliesToRelationshipsAsWell()
        {
            Console.WriteLine();
            Console.WriteLine("[TEST] CM5: the relationship half replaces collections too");

            var engine = new TradeCopierEngine();
            engine.UpsertRelationship(Cm2Relationship());   // MES=3.0, MNQ=5.0

            var merged = engine.ApplyRelationshipRequest(JObject.Parse(
                @"{""leaderAccount"":""Cm2Leader"",""followerAccount"":""Cm2Follower"",""perTickerRatios"":{""MES"":9.0}}"),
                false);

            Assert(merged != null && merged.PerTickerRatios != null && merged.PerTickerRatios.Count == 1,
                "the relationship's table is exactly what was sent");
            double v = 0.0;
            Assert(merged != null && merged.PerTickerRatios != null
                   && merged.PerTickerRatios.TryGetValue("mes", out v) && v == 9.0,
                "and is still OrdinalIgnoreCase");
            Assert(merged != null && merged.MaxSlippageTicks == 2.5,
                "while unmentioned scalar fields are still preserved");
        }

        // ================================================================================
        // P2-93: pure and override_with_friction pass preflight's enforcement gate but
        // IsActingMode() returns true only for "live", so ProcessAction answers SHADOW (SKIPPED)
        // for both. An operator waits out five shadow sessions to reach a mode that enforces
        // nothing. Fail-closed: preflight must refuse to arm in either mode.
        // ================================================================================
        private static void TestP293_PureAndOverrideWithFrictionFailPreflight()
        {
            Console.WriteLine("\n[TEST] P2-93: pure and override_with_friction fail preflight (not implemented)");

            foreach (var mode in new[] { "pure", "override_with_friction" })
            {
                var addon = new RiskGuardAddOn();
                var config = new RiskConfig();
                config.Mode = mode;
                config.MinShadowSessions = 0; // clear the shadow-session gate to isolate this check
                addon.SetConfigForTest(config);
                addon.SetModeForTest(mode);
                addon.SetArmedForTest(true);

                // Need at least one connected non-excluded account for preflight
                Account.All.Clear();
                Account.All.Add(new Account { Name = "P293Acc" });

                var result = addon.RunPreflight();
                Assert(!result.Passed, string.Format(
                    "preflight must FAIL in '{0}' mode -- IsActingMode() returns true only for 'live', " +
                    "so ProcessAction would answer SHADOW (SKIPPED) for every breach", mode));
                Assert(result.FailureCode != null && result.FailureCode.Contains("MODE_NOT_IMPLEMENTED"),
                    string.Format("and the failure must name MODE_NOT_IMPLEMENTED so the operator knows why, in '{0}'", mode));
            }

            // And the paired negative: "live" and "shadow" must still pass (with MinShadowSessions cleared)
            foreach (var mode in new[] { "live", "shadow" })
            {
                var addon = new RiskGuardAddOn();
                var config = new RiskConfig();
                config.Mode = mode;
                config.MinShadowSessions = 0;
                addon.SetConfigForTest(config);
                addon.SetModeForTest(mode);

                Account.All.Clear();
                Account.All.Add(new Account { Name = "P293Acc" });

                var result = addon.RunPreflight();
                Assert(result.Passed, string.Format(
                    "preflight must PASS in '{0}' mode -- only pure and override_with_friction are refused", mode));
            }
        }

        // ================================================================================
        // P2-94: a TIMED manual lockout (LockAccount(name, minutes)) sets LockoutUntil but not
        // IsLockedOut. CanTrade read only IsLockedOut, so new orders were admitted and the sweep
        // then flattened the fills -- worse than a clean refusal. CanTrade must use the same
        // lockout test as the sweep: IsLockedOut || UtcNow < LockoutUntil.
        // ================================================================================
        private static void TestP294_ATimedManualLockoutStopsNewOrders()
        {
            Console.WriteLine("\n[TEST] P2-94: a timed manual lockout stops new orders (CanTrade reads LockoutUntil)");

            var addon = new RiskGuardAddOn();
            var config = new RiskConfig();
            addon.SetConfigForTest(config);
            addon.SetModeForTest("live");
            addon.SetArmedForTest(true);

            var state = new AccountState("P294Acc");
            addon.SetAccountStateForTest("P294Acc", state);

            // Before lockout: can trade
            Assert(addon.CanTrade("P294Acc", "MNQ 03-26", "P294"),
                "precondition: account is tradable before lockout");

            // Timed lockout for 60 minutes -- sets LockoutUntil but NOT IsLockedOut
            addon.LockAccount("P294Acc", 60);
            Assert(state.LockoutUntil > DateTime.UtcNow, "LockoutUntil is in the future");
            Assert(state.IsLockedOut == false, "IsLockedOut is false for timed lockout (the defect's shape)");

            // P2-94: CanTrade must refuse even though IsLockedOut is false
            Assert(!addon.CanTrade("P294Acc", "MNQ 03-26", "P294"),
                "P2-94: a timed manual lockout stops new orders -- CanTrade must read LockoutUntil, not just IsLockedOut");

            // And an EOD lockout (minutes == -1) must still bite (sets IsLockedOut, not LockoutUntil)
            addon.UnlockAccount("P294Acc");
            addon.LockAccount("P294Acc", -1);
            Assert(state.IsLockedOut == true, "EOD lock sets IsLockedOut");
            Assert(!addon.CanTrade("P294Acc", "MNQ 03-26", "P294"),
                "and an EOD manual lockout still stops new orders (regression guard)");

            // After unlock: can trade again
            addon.UnlockAccount("P294Acc");
            Assert(addon.CanTrade("P294Acc", "MNQ 03-26", "P294"),
                "after unlock the account is tradable again");
        }

        // ================================================================================
        // P2-95: FirmStartingBalance is captured as balance - realized - unrealized, and
        // realized is SESSION-scoped, so it is the session-start balance and not the plan's.
        // On an account up $5,000 over its life it reads 55,000 instead of 50,000, so the
        // trail-lock floor is wrong by lifetime profit. FirmProfile.AccountSize is the fix.
        // ================================================================================
        private static void TestP295_FirmStartingBalanceUsesPlanAccountSizeNotHeuristic()
        {
            Console.WriteLine("\n[TEST] P2-95: FirmStartingBalance uses plan AccountSize, not session-scoped heuristic");

            // A mapped account with a plan that states AccountSize = 50000.
            // The account has balance 55000, realized 5000 (lifetime profit), unrealized 0.
            // The heuristic would capture 55000 - 5000 - 0 = 50000 -- which happens to be right
            // ONLY because realized is session-scoped and this is the first session. On the next
            // session, realized resets to 0, so the heuristic captures 55000, which is wrong by
            // 5000. AccountSize is always 50000 regardless of session.
            var fm = new FirmMirrorConfig();
            fm.Enabled = true;
            fm.TrailingDD = new FirmTrailingDDConfig
            {
                Enabled = true, Type = "intraday", IncludesUnrealized = true,
                Amount = 2000.0, Buffer = 200.0, LockAtProfit = 2000.0
            };
            fm.FirmProfiles["TPT-50K-PRO"] = new FirmProfile
            {
                Name = "TPT-50K-PRO",
                AccountSize = 50000.0,
                TrailingDD = new FirmTrailingDDConfig
                {
                    Enabled = true, Type = "intraday", IncludesUnrealized = true,
                    Amount = 2000.0, Buffer = 200.0, LockAtProfit = 2000.0
                },
                DailyLoss = new FirmDailyLossConfig { Enabled = false }
            };
            fm.AccountFirmMap["P295Acc"] = "TPT-50K-PRO";

            var addon = new RiskGuardAddOn();
            var config = new RiskConfig();
            config.FirmMirror = fm;
            addon.SetConfigForTest(config);

            var account = new Account { Name = "P295Acc" };
            // Session 2: balance is 55000 (up 5000 lifetime), but realized is session-scoped
            // so realized = 0 this session. The heuristic captures 55000 - 0 - 0 = 55000.
            // AccountSize is 50000. The fix must use 50000.
            account.Values[AccountItem.CashValue] = 55000.0;
            account.Values[AccountItem.RealizedProfitLoss] = 0.0;
            account.Values[AccountItem.UnrealizedProfitLoss] = 0.0;

            var state = new AccountState("P295Acc");
            state.FirmDailyDate = FirmDailyDateFor(FirmTestClockUtc, fm);

            addon.EvaluateFirmMirror(account, state, FirmTestClockUtc);

            Assert(state.FirmStartingBalance == 50000.0,
                "P2-95: FirmStartingBalance must be the plan's AccountSize (50000), not the heuristic "
                + "(55000) -- the heuristic is session-scoped and wrong by lifetime profit");

            // And an UNMAPPED account (no plan, no AccountSize) must still use the heuristic
            var fm2 = new FirmMirrorConfig();
            fm2.Enabled = true;
            fm2.TrailingDD = new FirmTrailingDDConfig
            {
                Enabled = true, Type = "intraday", IncludesUnrealized = true,
                Amount = 2000.0, Buffer = 200.0, LockAtProfit = 0.0
            };

            var addon2 = new RiskGuardAddOn();
            var config2 = new RiskConfig();
            config2.FirmMirror = fm2;
            addon2.SetConfigForTest(config2);

            var account2 = new Account { Name = "P295Unmapped" };
            account2.Values[AccountItem.CashValue] = 55000.0;
            account2.Values[AccountItem.RealizedProfitLoss] = 0.0;
            account2.Values[AccountItem.UnrealizedProfitLoss] = 0.0;

            var state2 = new AccountState("P295Unmapped");
            state2.FirmDailyDate = FirmDailyDateFor(FirmTestClockUtc, fm2);

            addon2.EvaluateFirmMirror(account2, state2, FirmTestClockUtc);

            Assert(state2.FirmStartingBalance == 55000.0,
                "an unmapped account with no plan AccountSize falls back to the heuristic (55000) -- "
                + "the fix only applies when the plan states a size");
        }

        // ================================================================================
        // P3-31: in-flight order ledger for the copier reconciler.
        //
        // Between Submit and Accepted an order is in neither Account.Orders nor the
        // bracket cache, so a timer-driven reconciler would create a second leg. The
        // ledger records a submitted order's identity BEFORE the broker call and
        // removes it when the order appears in Account.Orders or the submit failed.
        // Reconcile's submitInFlight parameter is the seam -- it suppresses Create
        // only, never Cancel, so a reservation can delay placing a leg but never
        // delay removing an orphan (P0-50).
        //
        // These tests are authored BEFORE the implementation (test-first per §6.0).
        // They will not compile until InFlightLedger exists; that is the baseline-red
        // gate the agent loop requires.
        // ================================================================================

        private static void TestP331_InFlightLedgerSuppressesCreateUntilAccepted()
        {
            Console.WriteLine("\n[TEST] P3-31: the in-flight ledger suppresses Create until the order is Accepted");

            var ledger = new InFlightLedger();
            // Register a stop submit for account "F1", instrument "MNQ 03-26"
            ledger.Register("F1", "MNQ 03-26", "COPIER_STOP");

            Assert(ledger.IsInFlight("F1", "MNQ 03-26", "COPIER_STOP"),
                "immediately after Register, the leg is in-flight -- Reconcile must see submitInFlight=true");

            Assert(!ledger.IsInFlight("F1", "MNQ 03-26", "COPIER_TARGET"),
                "only the registered leg is in-flight, not the other leg");

            // Simulate the order appearing in Account.Orders (Accepted)
            ledger.Settle("F1", "MNQ 03-26", "COPIER_STOP");

            Assert(!ledger.IsInFlight("F1", "MNQ 03-26", "COPIER_STOP"),
                "after Settle, the leg is no longer in-flight -- a second pass may Create if needed");
        }

        private static void TestP331_LedgerEntryClearedOnAccepted()
        {
            Console.WriteLine("\n[TEST] P3-31: ledger entry is cleared when the order is Accepted");

            var ledger = new InFlightLedger();
            ledger.Register("F1", "MNQ 03-26", "COPIER_STOP");
            Assert(ledger.Count == 1, "one entry after Register");

            ledger.Settle("F1", "MNQ 03-26", "COPIER_STOP");
            Assert(ledger.Count == 0, "zero entries after Settle");
        }

        private static void TestP331_LedgerEntryClearedOnSubmitFailure()
        {
            Console.WriteLine("\n[TEST] P3-31: ledger entry is cleared when the submit returned null (failed)");

            var ledger = new InFlightLedger();
            ledger.Register("F1", "MNQ 03-26", "COPIER_STOP");
            Assert(ledger.Count == 1, "one entry after Register");

            // Submit returned null -- the order will never appear in Account.Orders
            ledger.Fail("F1", "MNQ 03-26", "COPIER_STOP");
            Assert(ledger.Count == 0, "zero entries after Fail -- a null submit must not permanently suppress Create");
        }

        private static void TestP331_StaleLedgerEntryIsClearedAfterTimeout()
        {
            Console.WriteLine("\n[TEST] P3-31: a stale ledger entry (never settled) is cleared after a timeout");

            var ledger = new InFlightLedger(timeoutSeconds: 2);
            ledger.Register("F1", "MNQ 03-26", "COPIER_STOP");
            Assert(ledger.Count == 1, "one entry after Register");

            // Wait past the timeout
            System.Threading.Thread.Sleep(2200);
            ledger.PurgeExpired();
            Assert(ledger.Count == 0, "zero entries after timeout -- a crashed submit must not permanently suppress Create");
        }

        private static void TestP331_TimerCreatesMissingLegWhenNoInFlight()
        {
            Console.WriteLine("\n[TEST] P3-31: a timer-driven reconcile Creates a missing leg when nothing is in-flight");

            // This test verifies the timer path feeds submitInFlight=false when the
            // ledger has no entry, so Reconcile emits Create for a missing leg.
            var ledger = new InFlightLedger();

            // No registration -- nothing is in-flight
            bool stopInFlight = ledger.IsInFlight("F1", "MNQ 03-26", "COPIER_STOP");
            Assert(!stopInFlight,
                "with no registration, IsInFlight is false -- Reconcile may Create the missing leg");
        }

        private static void TestP331_TimerDoesNotCreateDuplicateWhenInFlight()
        {
            Console.WriteLine("\n[TEST] P3-31: a timer-driven reconcile does NOT Create when the leg is already in-flight");

            var ledger = new InFlightLedger();
            ledger.Register("F1", "MNQ 03-26", "COPIER_STOP");

            bool stopInFlight = ledger.IsInFlight("F1", "MNQ 03-26", "COPIER_STOP");
            Assert(stopInFlight,
                "with a registration, IsInFlight is true -- Reconcile suppresses Create, preventing a duplicate leg");
        }

        // ================================================================================
        // P3-30: RiskGuard-side audit (naked position, orphan stop, FSM/broker divergence).
        //
        // The copier half shipped (reconciler + timer from P3-31). The guard half
        // needs a periodic audit that checks the FSM state against the broker on a
        // clock -- events alone miss a divergence with no subsequent event. The audit
        // is an observer: it emits LogEvent, never actions.
        //
        // These tests are authored BEFORE the implementation (test-first per 6.0).
        // They call RunAuditNow() which does not exist yet -- baseline red.
        // ================================================================================

        private static void TestP330_AuditDetectsNakedPosition()
        {
            Console.WriteLine("\n[TEST] P3-30: the audit detects a naked position");

            var addon = new RiskGuardAddOn();
            var config = new RiskConfig();
            addon.SetConfigForTest(config);
            addon.SetModeForTest("shadow");
            addon.SetArmedForTest(true);

            var account = new Account { Name = "P330Naked" };
            var state = new AccountState("P330Naked");
            addon.SetAccountStateForTest("P330Naked", state);
            addon.SetSubscribedAccountForTest("P330Naked");
            Account.All.Clear();
            Account.All.Add(account);

            // Give the account a position but no protective stop
            account.Positions.Add(new Position
            {
                Instrument = new Instrument("MNQ"),
                MarketPosition = MarketPosition.Long,
                Quantity = 1,
                AveragePrice = 18000
            });

            var events = new List<string>();
            RiskGuardAddOn.LogEventObserver = (acct, evt) => events.Add(acct + "/" + evt);
            try
            {
                addon.RunAuditNow();
            }
            finally { RiskGuardAddOn.LogEventObserver = null; }

            Assert(events.Any(e => e.StartsWith("P330Naked/NAKED_POSITION", StringComparison.Ordinal)),
                "the audit detects a naked position -- a position exists but no FSM is tracking it");
        }

        private static void TestP330_AuditDetectsOrphanStop()
        {
            Console.WriteLine("\n[TEST] P3-30: the audit detects an orphan stop");

            var addon = new RiskGuardAddOn();
            var config = new RiskConfig();
            addon.SetConfigForTest(config);
            addon.SetModeForTest("shadow");
            addon.SetArmedForTest(true);

            var account = new Account { Name = "P330Orphan" };
            var state = new AccountState("P330Orphan");
            addon.SetAccountStateForTest("P330Orphan", state);
            addon.SetSubscribedAccountForTest("P330Orphan");
            Account.All.Clear();
            Account.All.Add(account);

            // No positions, but a working stop order exists
            account.Orders.Add(new Order
            {
                Instrument = new Instrument("MNQ"),
                Name = "AUTO_STOP",
                OrderType = OrderType.StopMarket,
                OrderState = OrderState.Working,
                StopPrice = 17900,
                Quantity = 1,
                OrderAction = OrderAction.Sell
            });

            var events = new List<string>();
            RiskGuardAddOn.LogEventObserver = (acct, evt) => events.Add(acct + "/" + evt);
            try
            {
                addon.RunAuditNow();
            }
            finally { RiskGuardAddOn.LogEventObserver = null; }

            Assert(events.Any(e => e.StartsWith("P330Orphan/ORPHAN_STOP", StringComparison.Ordinal)),
                "the audit detects an orphan stop -- a working stop exists but the position is flat");
        }

        private static void TestP330_AuditDetectsFsmBrokerDivergence()
        {
            Console.WriteLine("\n[TEST] P3-30: the audit detects FSM/broker divergence");

            var addon = new RiskGuardAddOn();
            var config = new RiskConfig();
            addon.SetConfigForTest(config);
            addon.SetModeForTest("shadow");
            addon.SetArmedForTest(true);

            var account = new Account { Name = "P330Div" };
            var state = new AccountState("P330Div");
            addon.SetAccountStateForTest("P330Div", state);
            addon.SetSubscribedAccountForTest("P330Div");
            Account.All.Clear();
            Account.All.Add(account);

            // Give the account a position
            account.Positions.Add(new Position
            {
                Instrument = new Instrument("MNQ"),
                MarketPosition = MarketPosition.Long,
                Quantity = 1,
                AveragePrice = 18000
            });

            // Create an FSM that claims Protected
            var fsm = new PositionGuardFsm("P330Div", "MNQ");
            fsm.State = GuardFsmState.Protected;
            fsm.PositionQuantity = 1;
            // Add a recognized stop to the FSM so CoveredQuantity reads as 1
            fsm.AddRecognizedStop(new Order
            {
                Instrument = new Instrument("MNQ"),
                Name = "AUTO_STOP",
                OrderType = OrderType.StopMarket,
                OrderState = OrderState.Working,
                StopPrice = 17900,
                Quantity = 1,
                OrderAction = OrderAction.Sell
            });
            addon.SetFsmForTest("P330Div", "MNQ", fsm);

            // But the broker has NO working stop order (divergence -- the FSM's
            // recognized stop is not in account.Orders)

            var events = new List<string>();
            RiskGuardAddOn.LogEventObserver = (acct, evt) => events.Add(acct + "/" + evt);
            try
            {
                addon.RunAuditNow();
            }
            finally { RiskGuardAddOn.LogEventObserver = null; }

            Assert(events.Any(e => e.StartsWith("P330Div/FSM_DIVERGENCE", StringComparison.Ordinal)),
                "the audit detects FSM/broker divergence -- FSM says Protected but no working stop exists at the broker");
        }

        /// <summary>
        /// The three tests above are positive-only: each asserts that an event WAS emitted.
        /// None of them can fail if the audit's instrument matching is broken, because a
        /// total matching failure emits every event. This is the complement, and it is the
        /// only one of the four that can detect that class: a correctly protected account
        /// -- position, a working stop for it at the broker, and an FSM that says Protected
        /// with full coverage -- must produce SILENCE.
        /// </summary>
        private static void TestP330_AuditIsSilentOnACorrectlyProtectedAccount()
        {
            Console.WriteLine("\n[TEST] P3-30: the audit is SILENT on a correctly protected account");

            var addon = new RiskGuardAddOn();
            var config = new RiskConfig();
            addon.SetConfigForTest(config);
            addon.SetModeForTest("shadow");
            addon.SetArmedForTest(true);

            var account = new Account { Name = "P330Quiet" };
            var state = new AccountState("P330Quiet");
            addon.SetAccountStateForTest("P330Quiet", state);
            addon.SetSubscribedAccountForTest("P330Quiet");
            Account.All.Clear();
            Account.All.Add(account);

            // The instrument name is the one the REST of the addon keys FSMs by:
            // Instrument.FullName. Every production call site builds the key from
            // FullName (see the SeedFsms sweep and ExecutePositionUpdate).
            var mnq = new Instrument("MNQ 03-26");

            account.Positions.Add(new Position
            {
                Instrument = mnq,
                MarketPosition = MarketPosition.Long,
                Quantity = 1,
                AveragePrice = 18000
            });

            // The broker HAS the working stop that covers it.
            var brokerStop = new Order
            {
                Instrument = mnq,
                Name = "AUTO_STOP",
                OrderType = OrderType.StopMarket,
                OrderState = OrderState.Working,
                StopPrice = 17900,
                Quantity = 1,
                OrderAction = OrderAction.Sell
            };
            account.Orders.Add(brokerStop);

            var fsm = new PositionGuardFsm("P330Quiet", "MNQ 03-26");
            fsm.State = GuardFsmState.Protected;
            fsm.PositionQuantity = 1;
            fsm.AddRecognizedStop(brokerStop);
            addon.SetFsmForTest("P330Quiet", "MNQ 03-26", fsm);

            var events = new List<string>();
            RiskGuardAddOn.LogEventObserver = (acct, evt) => events.Add(acct + "/" + evt);
            try
            {
                addon.RunAuditNow();
            }
            finally { RiskGuardAddOn.LogEventObserver = null; }

            var naked = events.Where(e => e.Contains("NAKED_POSITION")).ToList();
            var orphan = events.Where(e => e.Contains("ORPHAN_STOP")).ToList();
            var divergence = events.Where(e => e.Contains("FSM_DIVERGENCE")).ToList();

            Assert(naked.Count == 0,
                "a fully covered position is not reported NAKED_POSITION -- got: "
                + string.Join(" | ", naked));
            Assert(orphan.Count == 0,
                "a stop that covers a live position is not reported ORPHAN_STOP -- got: "
                + string.Join(" | ", orphan));
            Assert(divergence.Count == 0,
                "a Protected FSM whose stop IS at the broker is not reported FSM_DIVERGENCE -- got: "
                + string.Join(" | ", divergence));
        }

        /// <summary>
        /// `account.Positions` can carry a Position that is flat. The FSM-seeding sweep has
        /// always filtered those (MarketPosition.Flat || Quantity &lt;= 0); the audit did not,
        /// so a flat account reported NAKED_POSITION on every tick of a 10-second timer.
        /// </summary>
        private static void TestP330_AuditIsSilentOnAFlatPositionObject()
        {
            Console.WriteLine("\n[TEST] P3-30: a FLAT Position object is not a naked position");

            var addon = new RiskGuardAddOn();
            addon.SetConfigForTest(new RiskConfig());
            addon.SetModeForTest("shadow");
            addon.SetArmedForTest(true);

            var account = new Account { Name = "P330Flat" };
            addon.SetAccountStateForTest("P330Flat", new AccountState("P330Flat"));
            addon.SetSubscribedAccountForTest("P330Flat");
            Account.All.Clear();
            Account.All.Add(account);

            // Flat, and no FSM tracking it -- which is correct, there is nothing to track.
            account.Positions.Add(new Position
            {
                Instrument = new Instrument("MNQ 03-26"),
                MarketPosition = MarketPosition.Flat,
                Quantity = 0,
                AveragePrice = 0
            });

            // And the OTHER half of the same filter, which the FSM-seeding sweep guards
            // separately: a side that is not Flat carrying no contracts. Asserting only the
            // MarketPosition shape leaves `Quantity <= 0` undefended, and a zero-quantity
            // position reports a gap of zero -- an alarm that names no risk.
            account.Positions.Add(new Position
            {
                Instrument = new Instrument("ES 03-26"),
                MarketPosition = MarketPosition.Long,
                Quantity = 0,
                AveragePrice = 5000
            });

            var events = new List<string>();
            RiskGuardAddOn.LogEventObserver = (acct, evt) => events.Add(acct + "/" + evt);
            try { addon.RunAuditNow(); }
            finally { RiskGuardAddOn.LogEventObserver = null; }

            var naked = events.Where(e => e.Contains("NAKED_POSITION")).ToList();
            Assert(naked.Count == 0,
                "a flat Position object is not reported NAKED_POSITION -- got: "
                + string.Join(" | ", naked));
        }

        /// <summary>
        /// The coverage comparison is one character wide and wrong in both directions if
        /// inverted: a partially covered position is P0-55's exact shape and is the single
        /// most important thing this audit exists to catch.
        /// </summary>
        private static void TestP330_AuditReportsPartialCoverageAsNaked()
        {
            Console.WriteLine("\n[TEST] P3-30: a PARTIALLY covered position is reported naked");

            var addon = new RiskGuardAddOn();
            addon.SetConfigForTest(new RiskConfig());
            addon.SetModeForTest("shadow");
            addon.SetArmedForTest(true);

            var account = new Account { Name = "P330Partial" };
            addon.SetAccountStateForTest("P330Partial", new AccountState("P330Partial"));
            addon.SetSubscribedAccountForTest("P330Partial");
            Account.All.Clear();
            Account.All.Add(account);

            var mnq = new Instrument("MNQ 03-26");

            // Two contracts live...
            account.Positions.Add(new Position
            {
                Instrument = mnq,
                MarketPosition = MarketPosition.Long,
                Quantity = 2,
                AveragePrice = 18000
            });

            // ...and a stop for ONE of them at the broker.
            var partialStop = new Order
            {
                Instrument = mnq,
                Name = "AUTO_STOP",
                OrderType = OrderType.StopMarket,
                OrderState = OrderState.Working,
                StopPrice = 17900,
                Quantity = 1,
                OrderAction = OrderAction.Sell
            };
            account.Orders.Add(partialStop);

            var fsm = new PositionGuardFsm("P330Partial", "MNQ 03-26");
            fsm.State = GuardFsmState.Protected;
            fsm.PositionQuantity = 2;
            fsm.AddRecognizedStop(partialStop);
            addon.SetFsmForTest("P330Partial", "MNQ 03-26", fsm);

            var events = new List<string>();
            RiskGuardAddOn.LogEventObserver = (acct, evt) => events.Add(acct + "/" + evt);
            try { addon.RunAuditNow(); }
            finally { RiskGuardAddOn.LogEventObserver = null; }

            var naked = events.Where(e => e.Contains("NAKED_POSITION")).ToList();
            Assert(naked.Count == 1,
                "a position covered 1-of-2 is reported NAKED_POSITION even though the FSM says "
                + "Protected -- got " + naked.Count + ": " + string.Join(" | ", naked));
            // The uncovered quantity is in the event's DETAIL string, which LogEventObserver
            // deliberately does not carry (see its declaration: pinning message text breaks on
            // every rewording). The count above is what kills an inverted comparison anyway.
        }

        /// <summary>
        /// P0-50's class is a stop left WORKING on a FLAT account: it becomes a new position in
        /// the opposite direction the moment it triggers. A stop sitting over a LIVE position is
        /// not that, whatever the FSM knows about it -- and the untracked-position case is
        /// already reported as NAKED_POSITION, so reporting it again under a name that means the
        /// opposite of the situation is worse than not reporting it.
        /// </summary>
        private static void TestP330_AuditDoesNotCallAStopOverALivePositionAnOrphan()
        {
            Console.WriteLine("\n[TEST] P3-30: a stop over a LIVE position is not an orphan stop");

            var addon = new RiskGuardAddOn();
            addon.SetConfigForTest(new RiskConfig());
            addon.SetModeForTest("shadow");
            addon.SetArmedForTest(true);

            var account = new Account { Name = "P330NotOrphan" };
            addon.SetAccountStateForTest("P330NotOrphan", new AccountState("P330NotOrphan"));
            addon.SetSubscribedAccountForTest("P330NotOrphan");
            Account.All.Clear();
            Account.All.Add(account);

            var mnq = new Instrument("MNQ 03-26");

            account.Positions.Add(new Position
            {
                Instrument = mnq,
                MarketPosition = MarketPosition.Long,
                Quantity = 1,
                AveragePrice = 18000
            });
            account.Orders.Add(new Order
            {
                Instrument = mnq,
                Name = "AUTO_STOP",
                OrderType = OrderType.StopMarket,
                OrderState = OrderState.Working,
                StopPrice = 17900,
                Quantity = 1,
                OrderAction = OrderAction.Sell
            });

            // Deliberately NO FSM: the guard is not tracking this instrument.

            var events = new List<string>();
            RiskGuardAddOn.LogEventObserver = (acct, evt) => events.Add(acct + "/" + evt);
            try { addon.RunAuditNow(); }
            finally { RiskGuardAddOn.LogEventObserver = null; }

            var orphan = events.Where(e => e.Contains("ORPHAN_STOP")).ToList();
            var naked = events.Where(e => e.Contains("NAKED_POSITION")).ToList();

            Assert(orphan.Count == 0,
                "a stop covering a live position is NOT an orphan stop even with no FSM -- got: "
                + string.Join(" | ", orphan));
            Assert(naked.Count == 1,
                "the untracked position is still reported, once, as NAKED_POSITION -- got "
                + naked.Count + ": " + string.Join(" | ", naked));
        }

        // ================================================================================
        // P1-57: stop identifying our own orders by name substring -- track by reference.
        //
        // The only thing stopping the copier from mirroring a mirrored stop is that
        // our legs are named COPIER_STOP/COPIER_TARGET. Replikanto copies leader names
        // verbatim (Stop1, Target1), so we read its mirrored stop as a genuine leader
        // stop. The fix: track orders by reference, not by name substring.
        // ================================================================================

        private static void TestP157_SubmittedOrderIsNotTreatedAsLeaderOrder()
        {
            Console.WriteLine("\n[TEST] P1-57: a submitted order is not treated as a leader order");

            var mnq = new Instrument("MNQ 03-26");
            var rel = new CopierRelationship
            {
                LeaderAccountName = "P157Leader",
                FollowerAccountName = "P157Follower",
                IsEnabled = true,
                FixedLotMode = true,
                FixedLotSize = 1,
                AutoSymbolConversion = false,
                MaxPositionSize = 100
            };

            TradeCopierEngine.Instance.ResetBracketsForTest();
            SetupCopyPath("P157Leader", "P157Follower", rel, 1, mnq, MarketPosition.Long);
            var leader = Account.All.First(a => a.Name == "P157Leader");
            var follower = Account.All.First(a => a.Name == "P157Follower");

            // A stop that we submitted on the follower account, named Stop1 (like Replikanto would)
            var ourStop = new Order
            {
                Instrument = mnq,
                Name = "Stop1",
                OrderType = OrderType.StopMarket,
                OrderState = OrderState.Working,
                StopPrice = 17900,
                Quantity = 1,
                OrderAction = OrderAction.Sell
            };
            follower.Orders.Add(ourStop);

            // Register it as our own (the real implementation would do this on Submit)
            TradeCopierEngine.Instance.RegisterSubmittedOrderForTest(ourStop);

            // Set up a second relationship: P157Follower -> P157Follower2
            var rel2 = new CopierRelationship
            {
                LeaderAccountName = "P157Follower",
                FollowerAccountName = "P157Follower2",
                IsEnabled = true,
                FixedLotMode = true,
                FixedLotSize = 1,
                AutoSymbolConversion = false,
                MaxPositionSize = 100
            };
            TradeCopierEngine.Instance.UpsertRelationship(rel2);

            var follower2 = new Account { Name = "P157Follower2" };
            Account.All.Add(follower2);

            // The COPIER_STOP arrives as a "leader order" on P157Follower
            // P1-57: this must be skipped because we submitted it
            TradeCopierEngine.Instance.OnLeaderOrderUpdate(follower, ourStop);

            var follower2Stops = follower2.Orders.Where(o => o.Name == "Stop1" || o.Name == "COPIER_STOP").ToList();
            Assert(follower2Stops.Count == 0,
                "P1-57: a submitted order (our own stop, named Stop1 like Replikanto would) is NOT "
                + "treated as a leader order to mirror onward -- it is tracked by reference, not by name");
        }

        private static void TestP157_NonSubmittedOrderWithCopierNameIsStillLeaderOrder()
        {
            Console.WriteLine("\n[TEST] P1-57: a non-submitted order with COPIER in its name IS treated as a leader order");

            var mnq = new Instrument("MNQ 03-26");
            var rel = new CopierRelationship
            {
                LeaderAccountName = "P157LeaderB",
                FollowerAccountName = "P157FollowerB",
                IsEnabled = true,
                FixedLotMode = true,
                FixedLotSize = 1,
                AutoSymbolConversion = false,
                MaxPositionSize = 100
            };

            TradeCopierEngine.Instance.ResetBracketsForTest();
            var follower = SetupCopyPath("P157LeaderB", "P157FollowerB", rel, 0, mnq, MarketPosition.Flat);
            var leader = Account.All.First(a => a.Name == "P157LeaderB");

            // Leader has a position
            leader.Positions.Add(new Position
            {
                Instrument = mnq,
                MarketPosition = MarketPosition.Long,
                Quantity = 1,
                AveragePrice = 18000
            });

            // A DIFFERENT copier placed an order named "COPIER_STOP" on the leader account.
            // We did NOT submit this order. P1-57: it must still be treated as a leader order.
            var foreignStop = new Order
            {
                Instrument = mnq,
                Name = "COPIER_STOP",
                OrderType = OrderType.StopMarket,
                OrderState = OrderState.Working,
                StopPrice = 17900,
                Quantity = 1,
                OrderAction = OrderAction.Sell
            };
            leader.Orders.Add(foreignStop);

            // NOT registered in _submittedOrders -- it is NOT ours

            // The copier sees this order. P1-57: with the old name-based filter,
            // OnLeaderOrderUpdate returned early because order.Name contains "COPIER".
            // With reference tracking, it must NOT return early -- the order is not ours.
            // The assertion checks that the order was processed (not filtered) by
            // verifying a bracket was created for the follower. If the order was
            // filtered, no bracket exists.
            TradeCopierEngine.Instance.OnLeaderOrderUpdate(leader, foreignStop);

            // Check if a bracket was created for this follower (meaning the order
            // was NOT filtered). A filtered order produces no bracket.
            bool bracketCreated = false;
            try { bracketCreated = TradeCopierEngine.Instance.HasBracketForTest("P157FollowerB", mnq.FullName); }
            catch { }
            Assert(bracketCreated,
                "P1-57: a non-submitted order with COPIER in its name IS still treated as a leader "
                + "order -- the name substring is no longer the filter; reference tracking is");
        }

        // ================================================================================
        // P1-13: concurrent-guard-event stress test (prerequisite for the threading inversion).
        //
        // The S-series (S4-S9) are sequential. The threading inversion turns six handlers
        // the dispatcher was implicitly serialising into genuinely concurrent ones.
        // Without a concurrent stress test, doing the inversion is how P1-40 shipped.
        // ================================================================================

        private static void TestP113_ConcurrentGuardEventsDoNotCorruptState()
        {
            Console.WriteLine("\n[TEST] P1-13: concurrent guard events do not corrupt state");

            // Fire N concurrent events on separate threads against the same account+instrument.
            // If the test infrastructure for this doesn't exist yet, the assertion below fails.
            int threadCount = 20;
            var addon = new RiskGuardAddOn();
            var config = new RiskConfig();
            addon.SetConfigForTest(config);
            addon.SetModeForTest("shadow");
            addon.SetArmedForTest(true);

            var account = new Account { Name = "P113Stress" };
            var state = new AccountState("P113Stress");
            addon.SetAccountStateForTest("P113Stress", state);
            addon.SetSubscribedAccountForTest("P113Stress");
            Account.All.Clear();
            Account.All.Add(account);

            var mnq = new Instrument("MNQ 03-26");

            var ready = new System.Threading.CountdownEvent(threadCount);
            var done = new System.Threading.CountdownEvent(threadCount);
            Exception[] errors = new Exception[threadCount];

            for (int i = 0; i < threadCount; i++)
            {
                int idx = i;
                System.Threading.Tasks.Task.Run(() =>
                {
                    ready.Signal();
                    ready.Wait();
                    try
                    {
                        // Mix of position, order, and execution events on the same account+instrument
                        addon.ExecutePositionUpdate(account, new PositionEventArgs
                        {
                            Position = new Position
                            {
                                Instrument = mnq,
                                MarketPosition = MarketPosition.Long,
                                Quantity = 1,
                                AveragePrice = 18000
                            }
                        });

                        addon.ExecuteOrderUpdate(account, new OrderEventArgs
                        {
                            Order = new Order
                            {
                                Instrument = mnq,
                                Name = "AUTO_STOP",
                                OrderType = OrderType.StopMarket,
                                OrderState = OrderState.Working,
                                StopPrice = 17900,
                                Quantity = 1,
                                OrderAction = OrderAction.Sell
                            }
                        });
                    }
                    catch (Exception ex) { errors[idx] = ex; }
                    finally { done.Signal(); }
                });
            }

            done.Wait(TimeSpan.FromSeconds(10));

            int errorCount = errors.Count(e => e != null);
            Assert(errorCount == 0,
                "the concurrent stress test completes without corruption -- " + threadCount
                + " threads, " + errorCount + " exception(s)");

            // Verify FSM state is consistent after concurrent access. Fire a final
            // position update synchronously to ensure the FSM exists regardless of
            // thread timing (CI may be slower than local).
            addon.ExecutePositionUpdate(account, new PositionEventArgs
            {
                Position = new Position
                {
                    Instrument = mnq,
                    MarketPosition = MarketPosition.Long,
                    Quantity = 1,
                    AveragePrice = 18000
                }
            });
            var fsm = addon.TestGetFsm("P113Stress", "MNQ 03-26");
            Assert(fsm != null, "the FSM was created for the concurrent position events");
        }

        // ================================================================================
        // P3-34: copier preflight -- verify followers before live arming.
        // ================================================================================

        private static void TestP334_CopierPreflightDetectsMissingFollower()
        {
            Console.WriteLine("\n[TEST] P3-34: the copier preflight detects a missing follower");

            TradeCopierEngine.Instance.ResetBracketsForTest();
            Account.All.Clear();
            Account.All.Add(new Account { Name = "P334Leader" });

            var rel = new CopierRelationship
            {
                LeaderAccountName = "P334Leader",
                FollowerAccountName = "P334Missing",
                IsEnabled = true,
                ArmedForLive = false
            };
            TradeCopierEngine.Instance.UpsertRelationship(rel);

            var result = TradeCopierEngine.Instance.RunCopierPreflight();
            Assert(!result.Passed,
                "P3-34: the copier preflight detects a missing follower account");
            Assert(result.Failures.Count > 0,
                "P3-34: the preflight reports at least one failure");
        }

        private static void TestP334_CopierPreflightPassesWhenAllFollowersConnected()
        {
            Console.WriteLine("\n[TEST] P3-34: the copier preflight passes when all followers are connected");

            TradeCopierEngine.Instance.ResetBracketsForTest();
            // Clear all relationships to isolate this test
            foreach (var r in TradeCopierEngine.Instance.GetRelationshipsForTest())
                TradeCopierEngine.Instance.RemoveRelationship(r.LeaderAccountName, r.FollowerAccountName);
            Account.All.Clear();
            Account.All.Add(new Account { Name = "P334LeaderB" });
            Account.All.Add(new Account { Name = "P334FollowerB" });

            var rel = new CopierRelationship
            {
                LeaderAccountName = "P334LeaderB",
                FollowerAccountName = "P334FollowerB",
                IsEnabled = true,
                ArmedForLive = false
            };
            TradeCopierEngine.Instance.UpsertRelationship(rel);

            var result = TradeCopierEngine.Instance.RunCopierPreflight();
            Assert(result.Passed,
                "P3-34: the copier preflight passes when all followers exist and are connected");
        }

        // ================================================================================
        // P2-25: the news shield can never fire in production because _newsEvents is
        // never loaded from disk. Fix: LoadNewsEventsFromDisk reads a JSON file and
        // populates _newsEvents, called from UpdateConfig when a path is configured.
        // ================================================================================

        private static void TestP225_NewsShieldLoadsEventsFromDisk()
        {
            Console.WriteLine("\n[TEST] P2-25: the news shield loads events from disk");

            var suite = PropFirmProtectionSuite.Instance;
            var savedConfig = suite.Config;
            suite.UpdateConfig(new PropFirmProtectionConfig { EnableNewsShield = true });

            // Write a temporary JSON file with a news event
            string tempPath = Path.GetTempFileName();
            try
            {
                var ev = new EconomicNewsEvent
                {
                    EventTimeUtc = DateTime.UtcNow,
                    Title = "CPI Release",
                    Currency = "USD",
                    Impact = "High"
                };
                File.WriteAllText(tempPath, JsonConvert.SerializeObject(new[] { ev }));

                int before = suite.NewsEventCount;
                suite.LoadNewsEventsFromDisk(tempPath);
                int after = suite.NewsEventCount;

                Assert(after > before,
                    "P2-25: LoadNewsEventsFromDisk populates the event list -- the news shield can now fire");

                bool inWindow = suite.IsInNewsWindow(DateTime.UtcNow, 2, 2);
                Assert(inWindow,
                    "P2-25: IsInNewsWindow returns true for an event at the current time with a 2-minute buffer");
            }
            finally
            {
                File.Delete(tempPath);
                // Restore singleton state so other tests are not affected
                lock (suite)
                {
                    suite.UpdateConfig(savedConfig ?? new PropFirmProtectionConfig());
                }
            }
        }
    }
}
#endif
